[\"Craft rod now\"] = \"\",\n            [\"Buy Now\"] = \"\",\n            [\"Buy Selected Rod\"] = \"\",\n            [\"Learn Selected Skills\"] = \"\",\n            [\"Reroll Until Trait\"] = \"\",\n            [\"Craft bait now\"] = \"\",\n            [\"Exchange now\"] = \"\",\n            [\"Claim Daily Rewards\"] = \"\",\n            [\"Check Resources\"] = \"\",\n            [\"Redeem All Codes\"] = \"\",\n            [\"Refresh List\"] = \"\",\n            [\"Delete Job ID\"] = \"Job ID\",\n            [\"Join by Job ID\"] = \"Job ID\",\n            [\"Check Current Players\"] = \"\",\n            [\"Teleport to Player\"] = \"\",\n            [\"Spectate Player\"] = \"\",\n            [\"Teleport To Current Weather\"] = \"\",\n            [\"Teleport to Recommend Island\"] = \"\",\n            [\"Teleport to selected NPC\"] = \"NPC\",\n            [\"Teleport to selected Secret Rod\"] = \"\",\n            [\"TP to MaA(\"Model\") then return end\n                if godEspHighlights[godModel] then return end\n                \n                -- Only handle it when the parent is a Folder\n                if not godModel.Parent or typeof(godModel.Parent) ~= \"Instance\" or not godModel.Parent:IsA(\"Folder\") then return end\n                \n                local attachPart = godModel:FindFirstChildWhichIsA(\"BasePart\")\n                if not attachPart then\n                    attachPart = godModel:FindFirstChildWhichIsA(\"BasePart\", true)\n                end\n                if not attachPart then return end\n                \n                local highlight = Instance.new(\"Highlight\")\n                highlight.FillColor = Color3.fromRGB(255, 215, 0)\n                highlight.FillTransparency = 0.4\n                highlight.OutlineColor = Color3.fromRGB(255, 255, 100)\n                highlight.OutlineTransparency = 0.2\n                highlight.Adornee = godModel\n                highlight.Parent = godModel\n                \n                local billboard = Instance.new(\"BillboardGui\")\n                billboard.Name = \"GodEspBillboard\"\n                billboard.Size = UDim2.new(0, 200, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2.5, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new(\"Frame\")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new(\"UICorner\")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new(\"TextLabel\")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(255, 215, 0)\n                label.Text = \"\u{2600}\u{FE0F} \" .. godModel.Name\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                godEspHighlights[godModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeGodEsp(godModel)\n                local data = godEspHighlights[godModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    godEspHighlights[godModel] = nil\n                end\n            end\n            \n            local function clearAllGodEsp()\n                for model, data in pairs(godEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                godEspHighlights = {}\n            end\n            \n            local function scanAllGods()\n                if not godFolder then return end\n                for _, child in ipairs(godFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        if not godEspHighlights[child] then\n                            pcall(function() createGodEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startGodEsp()\n                if godEspEnabled then return end\n                godEspEnabled = true\n                scanAllGods()\n                \n                if godFolder then\n                    local godAddedConn = godFolder.DescendantAdded:Connect(function(desc)\n                        if godEspEnabled and typeof(desc) == \"Instance\" and desc:IsA(\"Model\") and desc.Parent and typeof(desc.Parent) == \"Instance\" and desc.Parent:IsA(\"Folder\") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not godEspHighlights[desc] then\n                                    createGodEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = godAddedConn })\n                end\n                \n                godEspThread = task.spawn(function()\n                    while godEspEnabled do\n                        task.wait(10)\n                        if godEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(godEspHighlights) do\n                                    if not model.Parent then\n                                        removeGodEsp(model)\n                                    end\n                                end\n                                scanAllGods()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = \"God ESP\", Message = \"God ESP enabled!\", Duration = 2 })\n            end\n            \n            local function stopGodEsp()\n                godEspEnabled = false\n                if godEspThread then\n                    task.cancel(godEspThread)\n                    godEspThread = nil\n                end\n                clearAllGodEsp()\n                NexusLib:Notify({ Title = \"God ESP\", Message = \"God ESP disabled!\", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap(\"Toggle\", \"God ESP\", {\n                Name = \"God ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startGodEsp()\n                    else\n                        stopGodEsp()\n                    end\n                end\n            })), \"Toggle\", \"God ESP\", {\n                Name = \"God ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startGodEsp()\n                    else\n                        stopGodEsp()\n                    end\n                end\n            })\n        end\n        \n        -- ===== NPCs ESP =====\n        do\n            local npcEspEnabled = false\n            local npcEspThread = nil\n            local npcEspHighlights = {}\n            local npcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n            \n            local function createNpcEsp(npcModel)\n                if not npcModel or typeof(npcModel) ~= \"Instance\" or not npcModel:IsA(\"Model\") then return end\n                if npcEspHighlights[npcModel] then return end\n                \n                if not npcModel.Parent or typeof(npcModel.Parent) ~= \"Instance\" or not npcModel.Parent:IsA(\"Folder\") then return end\n                \n                local attachPart = npcModel:FindFirstChildWhichIsA(\"BasePart\")\n                if not attachPart then\n                    attachPart = npcModel:FindFirstChildWhichIsA(\"BasePart\", true)\n                end\n                if not attachPart then return end\n                \n                local highlight = Instance.new(\"Highlight\")\n                highlight.FillColor = Color3.fromRGB(255, 100, 0)\n                highlight.FillTransparency = 0.4\n                highlight.OutlineColor = Color3.fromRGB(255, 200, 50)\n                highlight.OutlineTransparency = 0.2\n                highlight.Adornee = npcModel\n                highlight.Parent = npcModel\n                \n                local billboard = Instance.new(\"BillboardGui\")\n                billboard.Name = \"NpcEspBillboard\"\n                billboard.Size = UDim2.new(0, 200, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2.5, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new(\"Frame\")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new(\"UICorner\")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new(\"TextLabel\")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(255, 150, 50)\n                label.Text = \"NPC | \" .. npcModel.Name\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                npcEspHighlights[npcModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeNpcEsp(npcModel)\n                local data = npcEspHighlights[npcModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    npcEspHighlights[npcModel] = nil\n                end\n            end\n            \n            local function clearAllNpcEsp()\n                for model, data in pairs(npcEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                npcEspHighlights = {}\n            end\n            \n            local function scanAllNpcs()\n                if not npcFolder then return end\n                for _, child in ipairs(npcFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        if not npcEspHighlights[child] then\n                            pcall(function() createNpcEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startNpcEsp()\n                if npcEspEnabled then return end\n                npcEspEnabled = true\n                scanAllNpcs()\n                \n                if npcFolder then\n                    local npcAddedConn = npcFolder.DescendantAdded:Connect(function(desc)\n                        if npcEspEnabled and typeof(desc) == \"Instance\" and desc:IsA(\"Model\") and desc.Parent and typeof(desc.Parent) == \"Instance\" and desc.Parent:IsA(\"Folder\") then\n                            task.wait(0.1)\n                            pcall(function()                 Duration = 2\n                                    })\n                                end\n                            end)\n                            task.wait(2)\n                        end\n                    end)\n                else\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusLib:Notify({ Title = \"Gacha\", Message = \"Stopped\", Duration = 2 })\n                end\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== EXCHANGE TAB =====\n-- ============================================================\ndo\n    local ExchangeTab = Window:CreateTab(\"Exchange\")\n    local ExchangeSection = ExchangeTab:CreateSection(\"Exchange Items\")\n\n    local exchangeAmount = 1\n    local exchangeType = \"Trait Reroll\"\n\n    Cfg.register(ExchangeSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Quantity\", {\n        Name = \"Quantity\",\n        Placeholder = \"1\",\n        Default = \"1\",\n        Callback = function(value)\n            local num = tonumber(value)\n            if num and num >= 1 then\n                exchangeAmount = math.floor(num)\n            else\n                exchangeAmount = 1\n            end\n        end\n    })), \"Textbox\", \"Quantity\", {\n        Name = \"Quantity\",\n        Placeholder = \"1\",\n        Default = \"1\",\n        Callback = function(value)\n            local num = tonumber(value)\n            if num and num >= 1 then\n                exchangeAmount = math.floor(num)\n            else\n                exchangeAmount = 1\n            end\n        end\n    })\n\n    Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose an item\", {\n        Name = \"Choose an item\",\n        Options = {\"Trait Reroll\", \"EssenceOrb\"},\n        Default = \"Trait Reroll\",\n        Callback = function(value) exchangeType = value end\n    })), \"Dropdown\", \"Choose an item\", {\n        Name = \"Choose an item\",\n        Options = {\"Trait Reroll\", \"EssenceOrb\"},\n        Default = \"Trait Reroll\",\n        Callback = function(value) exchangeType = value end\n    })\n\n    local exchangeMethodDropdown = Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Exchange Method\", {\n        Name = \"Exchange Method\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = NexusState.exchange.method or \"Instant\",\n        Callback = function(value) NexusState.exchange.method = value end\n    })), \"Dropdown\", \"Exchange Method\", {\n        Name = \"Exchange Method\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = NexusState.exchange.method or \"Instant\",\n        Callback = function(value) NexusState.exchange.method = value end\n    })\n\n    ExchangeSection:CreateButton({\n        Name = \"Exchange now\",\n        Callback = function()\n            local userId = LocalPlayer.UserId\n            local userData = Data:FindFirstChild(tostring(userId))\n            if not userData then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Player data not found!\", Duration = 2 })\n                return\n            end\n            local crystal = userData:FindFirstChild(\"Crystal\")\n            local cash = userData:FindFirstChild(\"Cash\")\n            if not crystal or not cash then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Crystal or Cash not found!\", Duration = 2 })\n                return\n            end\n            local qty = exchangeAmount\n            local crystalNeed = qty * 5\n            local cashNeed = qty * 5000000\n            if crystal.Value < crystalNeed then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Not enough Crystals! Need \" .. crystalNeed .. \", have \" .. crystal.Value, Duration = 3 })\n                return\n            end\n            if cash.Value < cashNeed then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Not enough Cash! Need \" .. cashNeed .. \", have \" .. cash.Value, Duration = 3 })\n                return\n            end\n\n            NexusState.exchange.teleported = false\n            NexusState.exchange.oldPosition = nil\n            if NexusState.exchange.method == \"Teleport\" then\n                local npc = Workspace:FindFirstChild(\"NPC\")\n                if npc then\n                    local func = npc:FindFirstChild(\"Function\")\n                    if func then\n                        local nanjiang = func:FindFirstChild(\"Nanjiang\")\n                        if typeof(nanjiang) == \"Instance\" and nanjiang:IsA(\"Model\") then\n                            local hrp = nanjiang:FindFirstChild(\"HumanoidRootPart\")\n                            if hrp then\n                                local char = LocalPlayer.Character\n                                if char then\n                                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                    if root then\n                                        NexusState.exchange.oldPosition = root.Position\n                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                        NexusState.exchange.teleported = true\n                                        task.wait(0.3)\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                if not NexusState.exchange.teleported then\n                    NexusLib:Notify({ Title = \"Exchange\", Message = \"Could not find Nanjiang, teleport failed. Continuing anyway.\", Duration = 3 })\n                end\n            end\n\n            local success, err = pcall(function()\n                Events.Exchange:FireServer(exchangeType, qty)\n            end)\n\n            if NexusState.exchange.teleported and NexusState.exchange.oldPosition then\n                task.wait(0.2)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.exchange.oldPosition)\n                        NexusState.exchange.oldPosition = nil\n                        NexusState.exchange.teleported = false\n                    end\n                end\n            end\n\n            if success then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Exchanged \" .. qty .. \" \" .. exchangeType .. \"!\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Exchange failed: \" .. tostring(err), Duration = 2 })\n            end\n        end\n    })\nend\n\n-- ============================================================\n-- ===== QUESTS TAB =====\n-- ============================================================\ndo\n    local QuestsTab = Window:CreateTab(\"Quests\")\n\n    -- Teleport to Ticket Quest Giver, open dialogue, fire action, go back.\n    -- StartDialogue first: server ignores ChooseDialogueOption with no open dialogue.\n    NexusState.ticketLastFire = NexusState.ticketLastFire or 0\n    NexusState.ticketFailCount = NexusState.ticketFailCount or 0\n    local function ticketGoFire(action)\n        if _G and _G.Events then\n            local sd = _G.Events:FindFirstChild(\"StartDialogue\")\n            local cd = _G.Events:FindFirstChild(\"ChooseDialogueOption\")\n            if not sd or not cd then return false end\n        end\n        local giver = nil\n        pcall(function()\n            local npc = Workspace:FindFirstChild(\"NPC\")\n            local npcFunc = npc and npc:FindFirstChild(\"Function\")\n            giver = npcFunc and npcFunc:FindFirstChild(\"Ticket Quest Giver\")\n        end)\n        if not giver then return false end\n        local extraData = { giver }\n        local charNow = LocalPlayer.Character\n        local root = charNow and charNow:FindFirstChild(\"HumanoidRootPart\")\n        local giverPos = nil\n        pcall(function()\n            if typeof(giver) == \"Instance\" and typeof(giver) == \"Instance\" and giver:IsA(\"Model\") then\n                local hrp = giver:FindFirstChild(\"HumanoidRootPart\")\n                if hrp then\n                    giverPos = hrp.Position\n                elseif giver.PrimaryPart then\n                    giverPos = giver.PrimaryPart.Position\n                else\n                    giverPos = giver:GetPivot().Position\n                end\n            elseif typeof(giver) == \"Instance\" and typeof(giver) == \"Instance\" and giver:IsA(\"BasePart\") then\n                giverPos = giver.Position\n            end\n        end)\n        local origCF = root and root.CFrame\n        if root and giverPos then\n            pcall(function() root.CFrame = CFrame.new(giverPos + Vector3.new(0, 3, 0)) end)\n            task.wait(0.45)\n        end\n        pcall(function()\n            Events.StartDialogue:FireServer(\"Ticket Quest Giver\", giver)\n        end)\n        task.wait(0.25)\n        pcall(function()\n            Events.ChooseDialogueOption:FireServer(\"Ticket Quest Giver\", 1, action, extraData)\n        end)\n        task.wait(0.2)\n        if origCF and root and root.Parent then\n            pcall(function() root.CFrame = origCF end)\n        end\n        return true\n    end\n\n    -- ===== AUTO CLAIM TICKET QUEST =====\n    do\n        local ClaimSection = QuestsTab:CreateSection(\"Auto Claim Ticket Quest\")\n        local questTypes = {\"Easy Quest\", \"Hard Quest\"}\n        local selectedQuest = questTypes[1]\n\n        local function HasActiveQuest()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false end\n            local quest = userData:FindFirstChild(\"Quest\")\n            if not quest then return false end\n            local main = quest:FindFirstChild(\"Main\")\n            if not main then return false end\n            for _, child in pairs(main:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Folder\") then\n                    local name = child.Name\n                    if name == \"Easy Ticket Quest\" or name == \"Hard Ticket Quest\" then\n                        return true\n                    end\n                end\n            end\n            return false\n        end\n\n        local claimDropdown = Cfg.register(ClaimSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Select Quest Type\", {\n            Name = \"Select Quest Type\",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })), \"Dropdown\", \"Select Quest Type\", {\n            Name = \"Select Quest Type\",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })\n\n        local autoClaimToggle = Cfg.register(ClaimSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Claim Ticket Quest (Fast)\", {\n            Name = \"Auto Claim Ticket Quest (Fast)\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    if tick() - (NexusState.ticketLastFire        Method = \"POST\",\n                Headers = { [\"Content-Type\"] = \"application/json\" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function sendSpiritWebhook()\n        sendDiscordWebhook(SPIRIT_WEBHOOK, \"SPIRIT\")\n    end\n\n    local function getCurrentWeatherUI()\n        local lp = LocalPlayer\n        if not lp then return nil end\n        local mg = lp:FindFirstChild(\"PlayerGui\") and lp.PlayerGui:FindFirstChild(\"MainGui\")\n        if mg then\n            local info = mg:FindFirstChild(\"Info\")\n            if info then\n                local infoFrame = info:FindFirstChild(\"Info\")\n                if infoFrame then\n                    local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                    if weatherFrame then\n                        local val = weatherFrame:FindFirstChild(\"Value\")\n                        if val and typeof(val) == \"Instance\" then\n                            local text = (typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val.Text or val.Value)\n                            return text:gsub(\"Weather:%s*\", \"\")\n                        end\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local scanQueued = false\n\n    local function collectNpcModels()\n        local out = {}\n        local npcFolder = Workspace:FindFirstChild(\"NPC\")\n        if npcFolder then\n            for _, sub in ipairs(npcFolder:GetChildren()) do\n                out[#out + 1] = sub\n                for _, m in ipairs(sub:GetChildren()) do\n                    out[#out + 1] = m\n                end\n            end\n        end\n        return out\n    end\n\n    local function runNpcScan()\n        if game.JobId ~= NexusState.reportedJobId then\n            NexusState.reportedJobId = game.JobId\n            NexusState.LastMaoshan = false\n            NexusState.LastTaoist = false\n            NexusState.LastSpirit = false\n            NexusState.LastWeather = nil\n        end\n\n        local npcScan = (ScanMaoshan or ScanTaoist) and collectNpcModels() or {}\n\n        if ScanMaoshan then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == \"Instance\" and v:IsA(\"Model\") and (string.find(v.Name:lower(), \"maoshan\") or string.find(v.Name:lower(), \"merchant\")) and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastMaoshan then\n                NexusState.LastMaoshan = true\n                sendDiscordWebhook(MAOSHAN_WEBHOOK, \"Maoshan NPC\")\n            elseif not found then\n                NexusState.LastMaoshan = false\n            end\n        end\n\n        if ScanTaoist then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == \"Instance\" and v:IsA(\"Model\") and string.find(v.Name:lower(), \"taoist\") and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastTaoist then\n                NexusState.LastTaoist = true\n                sendDiscordWebhook(TAOIST_WEBHOOK, \"Taoist NPC\")\n            elseif not found then\n                NexusState.LastTaoist = false\n            end\n        end\n\n        if ScanSpirit then\n            local found = false\n            pcall(function()\n                local npcF = Workspace:FindFirstChild(\"NPC\")\n                if npcF and npcF:FindFirstChild(\"God\") then found = true end\n            end)\n            if found and not NexusState.LastSpirit then\n                NexusState.LastSpirit = true\n                sendSpiritWebhook()\n            elseif not found then\n                NexusState.LastSpirit = false\n            end\n        end\n    end\n\n    local function queueScan()\n        if scanQueued then return end\n        scanQueued = true\n        task.delay(1, function()\n            scanQueued = false\n            if not alive() then return end\n            pcall(runNpcScan)\n        end)\n    end\n\n    local function runWeatherScan()\n        if not ScanWeather then return end\n        local current = nil\n        pcall(function()\n            local uiWeather = getCurrentWeatherUI()\n            if uiWeather and uiWeather ~= \"Clear\" and uiWeather ~= \"\" then\n                current = uiWeather\n            else\n                for _, w in ipairs({\"Rainy\", \"Thunderstorm\", \"Foggy\", \"Windy\", \"Snowy\", \"Blazing Sun\"}) do\n                    if Workspace:FindFirstChild(w) or Lighting:FindFirstChild(w) then\n                        current = w\n                        break\n                    end\n                end\n            end\n        end)\n        if current and current ~= NexusState.LastWeather and current:lower() ~= \"clear\" then\n            NexusState.LastWeather = current\n            sendWeatherWebhook(WEATHER_WEBHOOK, current)\n        end\n    end\n\n    task.spawn(function()\n        local npcFolder = Workspace:WaitForChild(\"NPC\", 30)\n        if npcFolder then\n            npcFolder.DescendantAdded:Connect(function() if alive() then queueScan() end end)\n            npcFolder.DescendantRemoving:Connect(function() if alive() then queueScan() end end)\n        end\n\n        pcall(function()\n            local mg = LocalPlayer:WaitForChild(\"PlayerGui\", 30):WaitForChild(\"MainGui\", 30)\n            local info = mg and mg:WaitForChild(\"Info\", 15)\n            local infoFrame = info and info:WaitForChild(\"Info\", 15)\n            local weatherFrame = infoFrame and infoFrame:WaitForChild(\"Weather\", 15)\n            local val = weatherFrame and weatherFrame:WaitForChild(\"Value\", 15)\n            if val and typeof(val) == \"Instance\" then\n                local signal = (typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val:GetPropertyChangedSignal)(\"Text\") or val:GetPropertyChangedSignal(\"Value\")\n                signal:Connect(function() if alive() then runWeatherScan() end end)\n            end\n        end)\n\n        task.wait(2)\n        if alive() then\n            pcall(runNpcScan)\n            pcall(runWeatherScan)\n        end\n    end)\n]]\n\n-- ============================================================\n-- ===== MAIN LOOPS (Boss Farm, Auto Sell, GUI QTE) =====\n-- ============================================================\nlocal function GetInventoryLimit()\n    local userFolder = GetPlayerData()\n    if not userFolder then return 0 end\n    local sum = 0\n    pcall(function()\n        for _, v in pairs(userFolder.Inventory:GetChildren()) do sum = sum + 1 end\n        for _, v in pairs(userFolder.Hotbar:GetChildren()) do sum = sum + v.Quantity.Value end\n    end)\n    return sum\nend\n\nlocal function IsInventoryFull()\n    local userFolder = GetPlayerData()\n    if not userFolder then return false end\n    local limit = 0\n    pcall(function() limit = userFolder.InventoryLimit.Value end)\n    return GetInventoryLimit() >= limit\nend\n\nlocal GuiService = Services.GuiService\nlocal nexusPanel = LocalPlayer.PlayerGui:FindFirstChild(\"NexusPanel\")\n\nlocal function DisableNexusKeyboardActivation(object)\n    if typeof(object) == \"Instance\" and object:IsA(\"GuiObject\") then\n        object.Selectable = false\n    end\nend\n\nif runtimeEnv.NexusSpaceGuardConnection then\n    runtimeEnv.NexusSpaceGuardConnection:Disconnect()\n    runtimeEnv.NexusSpaceGuardConnection = nil\nend\nif runtimeEnv.NexusSelectableGuardConnection then\n    runtimeEnv.NexusSelectableGuardConnection:Disconnect()\n    runtimeEnv.NexusSelectableGuardConnection = nil\nend\n\nif nexusPanel then\n    DisableNexusKeyboardActivation(nexusPanel)\n    for _, object in ipairs(nexusPanel:GetDescendants()) do\n        DisableNexusKeyboardActivation(object)\n    end\n    runtimeEnv.NexusSelectableGuardConnection = nexusPanel.DescendantAdded:Connect(function(object)\n        task.defer(DisableNexusKeyboardActivation, object)\n    end)\nend\n\nruntimeEnv.NexusSpaceGuardConnection = UserInputService.InputBegan:Connect(function(input)\n    if input.KeyCode == Enum.KeyCode.Space then\n        local selected = GuiService.SelectedObject\n        if selected and nexusPanel and selected:IsDescendantOf(nexusPanel) then\n            GuiService.SelectedObject = nil\n        end\n    end\nend)\n\nlocal function castRod()\n    if not bossFarmEnabled() or tick() - Fishing.BossFarm.LastCast < 0.35 then return false end\n    local character = LocalPlayer.Character\n    if not character then return false end\n    if character:GetAttribute(\"Fishing\") and not character:GetAttribute(\"Retractable\") then return false end\n    -- Chong cau tren troi: dang bay / khong o tren nuoc thi bo qua lan cast nay\n    if not NexusState.canCastNow() then return false end\n    Fishing.BossFarm.LastCast = tick()\n    resetBossFarmTarget()\n    pcall(function()\n        local root = character:FindFirstChild(\"HumanoidRootPart\")\n        if root then Events.Fishing:FireServer(root.CFrame) end\n    end)\n    return true\nend\n\nlocal function farmHookedBoss(target)\n    if not bossFarmEnabled() then return end\n    local shouldFarm, targetType = shouldFarmBossTarget(target)\n    if not shouldFarm then return end\n    Fishing.BossFarm.CurrentType = targetType\n    local notifyKey = targetType .. tostring(target.Name)\n    if Fishing.BossFarm.LastNotify ~= notifyKey then\n        Fishing.BossFarm.LastNotify = notifyKey\n        NexusLib:Notify({ Title = \"Boss Farm\", Message = \"Farming \" .. targetType .. \": \" .. tostring(target.Name or \"Unknown\"), Duration = 3 })\n    end\n    if tick() - Fishing.BossFarm.LastProgress > 0.04 then\n        Fishing.BossFarm.LastProgress = tick()\n        pcall(function() Events.UpdateFishProgression:FireServer() end)\n    end\nend\n\n-- MAIN LOOPS\ntask.spawn(function()\n    while true do\n        local waitTime = 0.5 + math.random(0, 30) / 100\n        task.wait(waitTime)\n        if not alive() then break end\n        if Fishing.Flags.MainFarm and (Fishing.Flags.AutoCast or Fishing.Flags.AutoSkill or Fishing.Flags.AntiAFK) then\n            if Fishing.Flags.AutoCast then\n                local c = LocalPlayer.Character\n                if c then\n                    -- Fix freeze: khong force cast khi player dang di chuyen\n                    local moving = false\n                    pcall(function()\n                        local hum = c:FindFirstChildOfClass(\"Humanoid\")\n                        if hum and hum.MoveDirection then\n                            local md = hum.MoveDirection\n                            moving = math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05\n                        end\n                    end)\n                    if (not c:GetAttribute(\"Fishing\")) and not moving and NexusState.canCastNow() then\n                        pcall(function() Events.Fishing:FireServer() end)\n                    elseif NexusState.isDoingUseBaitQuest and MainGui:FindFirstChild(\"Fishing\") and MainGui.Fishing.Visible then\n                        pcall(function()\n                            local root = c:FindFirstChild(\"HumanoidRootPart\")\n                            Events.Fishing:FireServer(root and root.CFrame or nil)\n                        end)\n                    end\n                end\n            end\n            if Fishing.Flags.AutoSkill and MainGui:FindFirstChild(\"Fishing\") and MainGui.Fishing.Visible then\n                pcall(function()\n                    local char = LocalPlayer.Character\n                    local skillsFolder = char and char:FindFirstChild(\"Skills\")\n                    if skillsFolder then\n                        local readySkills = {}\n               eturn end\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            for _, v in ipairs(pg:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        pcall(function()\n            local cg = game:GetService(\"CoreGui\")\n            if cg then\n                for _, v in ipairs(cg:GetDescendants()) do\n                    replaceTextInObject(v)\n                end\n            end\n        end)\n    end\n\n    function NexusState.enableFakeName()\n        if NexusState.fakeNameEnabled then return end\n        NexusState.fakeNameEnabled = true\n        applyFakeNameToAll()\n\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            fakeNameConn = pg.DescendantAdded:Connect(function(desc)\n                if NexusState.fakeNameEnabled then\n                    task.wait(0.05)\n                    replaceTextInObject(desc)\n                end\n            end)\n        end\n\n        fakeNameThread = task.spawn(function()\n            while NexusState.fakeNameEnabled do\n                pcall(applyFakeNameToAll)\n                task.wait(1.5)\n            end\n        end)\n        NexusLib:Notify({ Title = \"Streamer Mode\", Message = \"Fake name active: \" .. tostring(NexusState.fakeName), Duration = 2 })\n    end\n\n    function NexusState.disableFakeName()\n        NexusState.fakeNameEnabled = false\n        if fakeNameConn then fakeNameConn:Disconnect(); fakeNameConn = nil end\n        if fakeNameThread then task.cancel(fakeNameThread); fakeNameThread = nil end\n        NexusLib:Notify({ Title = \"Streamer Mode\", Message = \"Fake name disabled\", Duration = 2 })\n    end\nend\n\n-- Chong \"cau tren troi\": khi dang bay / vua teleport, player lo lung tren khong\n-- nen phao khong roi trung nuoc -> cast phi hoai. Raycast xuong kiem tra nuoc.\nfunction NexusState.isOverWater()\n    local ok, result = pcall(function()\n        local char = LocalPlayer.Character\n        local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n        if not root then return false end\n\n        local params = RaycastParams.new()\n        params.FilterType = Enum.RaycastFilterType.Exclude\n        params.FilterDescendantsInstances = { char }\n        params.IgnoreWater = false\n\n        local hit = Workspace:Raycast(root.Position, Vector3.new(0, -200, 0), params)\n        if not hit then return false end\n\n        if hit.Instance == Workspace.Terrain and hit.Material == Enum.Material.Water then\n            return true\n        end\n        local n = string.lower(hit.Instance.Name)\n        if string.find(n, \"water\") or string.find(n, \"ocean\") or string.find(n, \"sea\") then\n            return true\n        end\n        return false\n    end)\n    if not ok then return true end -- loi thi cho cast, khong chan oan\n    return result\nend\n\nfunction NexusState.canCastNow()\n    if NexusState.flying then return false end\n    -- Khi bat auto cast / farm boss / farm secret: tele len troi la chu y\n    -- (chong detect), vay isOverWater se false -> bo qua kiem tra nuoc,\n    -- chi chan khi dang fly thu cong.\n    local F = NexusState.Fishing and NexusState.Fishing.Flags\n    if F and (F.AutoCast or F.AutoFarmBoss or F.AutoFarmSecretBoss) then\n        return true\n    end\n    return NexusState.isOverWater()\nend\n\n-- ============================================================\n-- ===== UNIVERSAL BAIT MERCHANT LOCATOR =====\n-- ============================================================\nlocal function findBaitMerchantHRP()\n    local char = LocalPlayer.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    local myPos = root and root.Position or Vector3.new(0, 0, 0)\n    local bestHRP = nil\n    local bestDist = math.huge\n\n    pcall(function()\n        local npcFolder = Workspace:FindFirstChild(\"NPC\")\n        if npcFolder then\n            local bb = npcFolder:FindFirstChild(\"BuyBait\")\n            if bb then\n                for _, model in ipairs(bb:GetChildren()) do\n                    if typeof(model) == \"Instance\" and typeof(model) == \"Instance\" and model:IsA(\"Model\") then\n                        local hrp = model:FindFirstChild(\"HumanoidRootPart\") or model:FindFirstChild(\"Torso\") or model.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n            local func = npcFolder:FindFirstChild(\"Function\")\n            if func then\n                for _, model in ipairs(func:GetChildren()) do\n                    if typeof(model) == \"Instance\" and typeof(model) == \"Instance\" and model:IsA(\"Model\") and (string.find(model.Name:lower(), \"bait\") or string.find(model.Name:lower(), \"shop\") or string.find(model.Name:lower(), \"merchant\")) then\n                        local hrp = model:FindFirstChild(\"HumanoidRootPart\") or model:FindFirstChild(\"Torso\") or model.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n            if not bestHRP then\n                for _, desc in ipairs(npcFolder:GetDescendants()) do\n                    if typeof(desc) == \"Instance\" and typeof(desc) == \"Instance\" and desc:IsA(\"Model\") and string.find(desc.Name:lower(), \"bait\") then\n                        local hrp = desc:FindFirstChild(\"HumanoidRootPart\") or desc:FindFirstChild(\"Torso\") or desc.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end)\n    return bestHRP\nend\n\n-- ===== BUILD MAIN UI =====\nruntimeEnv.NexusStage(\"dung UI\")\nlocal Window\ndo\n    local ok, result = pcall(function()\n        return NexusLib:CreateWindow({\n            Title = \"NEXUS\",\n            Subtitle = \"HEAVYWEIGHT FISHING - LIVE SESSION\",\n            Keybind = Enum.KeyCode.RightAlt,\n        })\n    end)\n    if not ok or type(result) ~= \"table\" then\n        runtimeEnv.NexusStage(\"UI window failed\")\n        runtimeEnv.NexusReport(\"Nexus UI failed\", \"CreateWindow: \" .. tostring(result))\n        return\n    end\n    Window = result\nend\n\nlocal Fishing = NexusState.Fishing\nlocal MiscFlags = NexusState.MiscFlags\n\n-- ============================================================\n-- ===== SHARED HELPERS (DECLARED UP FRONT) =====\n-- ============================================================\n\nlocal function GetPlayerData()\n    if not Data then return nil end\n    return Data:FindFirstChild(tostring(LocalPlayer.UserId))\nend\n\nlocal function GetModule(folder, name)\n    local m = folder:FindFirstChild(name)\n    if m then\n        local ok, mod = pcall(require, m)\n        if ok and type(mod) == \"table\" then return mod end\n    end\n    return nil\nend\n\nlocal function GetAvailableBaits()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local baits = {}\n    local baitFolder = p:FindFirstChild(\"Bait\")\n    if not baitFolder then return {} end\n    for _, b in pairs(baitFolder:GetChildren()) do\n        if typeof(b) == \"Instance\" and typeof(b) == \"Instance\" and b:IsA(\"NumberValue\") and b.Value > 0 then\n            table.insert(baits, b.Name)\n        end\n    end\n    return baits\nend\n\nlocal function GetBaitStats(baitName)\n    local mod = GetModule(Info.Bait, baitName)\n    if mod then return {Luck = mod.Luck or 0} end\n    return {Luck = 0}\nend\n\nlocal function GetBestBait()\n    local baits = GetAvailableBaits()\n    local best, bestLuck = nil, -1\n    for _, name in ipairs(baits) do\n        local s = GetBaitStats(name)\n        if s.Luck > bestLuck then bestLuck = s.Luck; best = name end\n    end\n    return best\nend\n\nlocal function EquipBait(baitName)\n    if not baitName then return false end\n    return pcall(function() Events.EquipBait:InvokeServer(baitName) end)\nend\n\nlocal function GetOwnedRods()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local rods = {}\n    for _, f in pairs(p.FishingRodInventory:GetChildren()) do\n        if typeof(f) == \"Instance\" and typeof(f) == \"Instance\" and f:IsA(\"Folder\") and f.Owned and f.Owned.Value == true then\n            table.insert(rods, f.Name)\n        end\n    end\n    return rods\nend\n\nlocal function GetRodStats(rodName)\n    local mod = GetModule(Info.Inventory, rodName)\n    if mod then return {Power = mod.Power or 0, Luck = mod.Luck or 0} end\n    return {Power = 0, Luck = 0}\nend\n\nlocal function GetBestRod()\n    local rods = GetOwnedRods()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(rods) do\n        local s = GetRodStats(name)\n        local score = s.Power + s.Luck\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipRod(rodName)\n    if not rodName then return false end\n    return pcall(function() Events.EquipFishingRod:InvokeServer(rodName) end)\nend\n\nlocal function GetAvailableOrbs()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local orbs = {}\n    local orbFolder = p:FindFirstChild(\"Orb\")\n    if not orbFolder then return {} end\n    for _, f in pairs(orbFolder:GetChildren()) do\n        if typeof(f) == \"Instance\" and typeof(f) == \"Instance\" and f:IsA(\"Folder\") then\n            local eq = f:FindFirstChild(\"Equipping\")\n            if eq and eq.Value == false then\n                table.insert(orbs, f.Name)\n            end\n        end\n    end\n    return orbs\nend\n\nlocal function GetOrbStats(orbName)\n    local p = GetPlayerData()\n    if not p then return {} end\n    local f = p.Orb:FindFirstChild(orbName)\n    if not f then return {} end\n    local stats = {}\n    for _, child in pairs(f:GetChildren()) do\n        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") and child.Name ~= \"Equipping\" and child.Name ~= \"Favorite\" then\n            stats[child.Name] = child.Value\n        end\n    end\n    return stats\nend\n\nlocal function GetBestOrb()\n    local orbs = GetAvailableOrbs()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(orbs) do\n        local s = GetOrbStats(name)\n        local score = (s.Damage or 0) * 2 + (s.Luck or 0) * 1.5 + (s.Cash or 0) * 0.5\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipOrb(orbName)\n    if not orbName then return false end\n    return pcall(function() Events.EquipOrb:InvokeServer(orbName) end)\nend\n\n-- Parse one Data inventory child into (fishName, weightKg, count).\n-- Real server format: Name = \"FishName | 3500000 KG\" (may add \" | Favorite\"),\n-- Value = stack count (IntValue). Older format kept as fallback.\nlocal function parseCraftWeight(str)\n    if not str or str == \"\" then return nil end\n    local s = tostring(str):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    s = s:gsub(\"%s*[Kk][Gg]%s*$\", \"\")\n    s = s:gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n",
