'etup")\n            if evP2 then\n                runtimeEnv.NexusNamelessP2 = evP2.OnClientEvent:Connect(function()\n                    if not alive() then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = "Auto Nameless", Message = "Nameless phase 2 [" .. tostring(Rhy.Mode) .. "]", Duration = 3 })\n                    end\n                end)\n            end\n        end)\n\n\n        runtimeEnv.NexusRhyLoop = RunService.Heartbeat:Connect(function()\n            if not alive() or not Rhy.Enabled then return end\n            local now = tick()\n            Rhy.Active = rhyUiActive() or now < (Rhy.SignalUntil or 0)\n            if not Rhy.Active then return end\n            if Rhy.Mode == "Risk" then rhyStartRisk() end\n            rhyScan(now)\n        end)\n\n        local NamelessSection = FarmingTab:CreateSection("Auto Nameless Octoparasite")\n        NamelessSection:CreateButton({\n            Name = "Teleport to Nameless Octoparasite",\n            Callback = function() pcall(rhyTeleportToNameless) end\n        })\n        Cfg.register(NamelessSection:CreateToggle(Cfg.wrap("Toggle", "Auto Nameless", {\n            Name = "Auto Nameless",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Enabled [" .. tostring(Rhy.Mode) .. "]. Waiting for Nameless signal from server.", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == "Risk" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Disabled | hit " .. tostring(Rhy.Stats.hit) .. " | remote " .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })), "Toggle", "Auto Nameless", {\n            Name = "Auto Nameless",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Enabled [" .. tostring(Rhy.Mode) .. "]. Waiting for Nameless signal from server.", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == "Risk" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Disabled | hit " .. tostring(Rhy.Stats.hit) .. " | remote " .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })\n    end\n\n    -- ===== FAVORITES =====\n    do\n        local FavSection = FarmingTab:CreateSection("Auto Favorite Fish")\n        local allFishNames = {}\n        pcall(function()\n            local rarityModule = require(Info.FishingAreaRarity)\n            if type(rarityModule) == "table" then\n                for _, fishTable in pairs(rarityModule) do\n                    if type(fishTable) == "table" then\n                        for fishName in pairs(fishTable) do\n                            if type(fishName) == "string" and fishName ~= "" then\n                                table.insert(allFishNames, fishName)\n                            end\n                        end\n                    end\n                end\n            end\n        end)\n        local uniqueFish = {}\n        for _, name in ipairs(allFishNames) do uniqueFish[name] = true end\n        local fishOptions = {}\n        for name in pairs(uniqueFish) do table.insert(fishOptions, name) end\n        table.sort(fishOptions)\n\n        local fishDropdown = Cfg.register(FavSection:CreateMultiDropdown(Cfg.wrap("MultiDropdown", "Select fish to auto-favourite", {\n            Name = "Select fish to auto-favourite",\n            Options = fishOptions,\n            Default = NexusState.favorites.selectedFish or {},\n            Callback = function(values) NexusState.favorites.selectedFish = values end\n        })), "MultiDropdown", "Select fish to auto-favourite", {\n            Name = "Select fish to auto-favourite",\n            Options = fishOptions,\n            Default = NexusState.favorites.selectedFish or {},\n            Callback = function(values) NexusState.favorites.selectedFish = values end\n        })\n\n        local autoFavToggle = Cfg.register(FavSection:CreateToggle(Cfg.wrap("Toggle", "Auto Favourite Fishes", {\n            Name = "Auto Favourite Fishes",\n            Default = false,\n            Callback = function(value)\n                NexusState.favorites.autoEnabled = value\n                if value then\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusState.favorites.thread = task.spawn(function()\n                        local favoriteEvent = Events:FindFirstChild("FavoriteItem")\n                        if not favoriteEvent then\n                            NexusLib:Notify({ Title = "Auto Favourite", Message = "FavoriteItem remote not found!", Duration = 3 })\n                            NexusState.favorites.autoEnabled = false\n                            if autoFavToggle and type(autoFavToggle.SetValue) == "function" then\n                                autoFavToggle:SetValue(false)\n                            end\n                            return\n                        end\n                        while NexusState.favorites.autoEnabled do\n                            pcall(function()\n                                local userId = LocalPlayer.UserId\n                                local userData = Data:FindFirstChild(tostring(userId))\n                                if not userData then return end\n                                local inventory = userData:FindFirstChild("Inventory")\n                                if not inventory then return end\n                                local selected = NexusState.favorites.selectedFish or {}\n                                if #selected == 0 then return end\n                                local selectedSet = {}\n                                for _, name in ipairs(selected) do selectedSet[name] = true end\n                                for _, item in pairs(inventory:GetChildren()) do\n                                    local fullName = item.Name\n                                    if not string.find(fullName, "| Favorite$") then\n                                        local fishName = fullName:match("^(.-)%s*|") or fullName\n                                        if selectedSet[fishName] then\n                                            favoriteEvent:FireServer(fullName)\n                                        end\n                                    end\n                                end\n                            end)\n                            task.wait(0.3)\n                        end\n                    end)\n                    NexusLib:Notify({ Title = "Auto Favourite", Message = "Enabled - scanning every 0.3s", Duration = 2 })\n                else\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusLib:Notify({ Title = "Auto Favourite", Message = "Disabled", Duration = 2 })\n                end\n            end\n        })), "Toggle", "Auto Favourite Fishes", {\n            Name = "Auto Favourite Fishes",\n            Default = false,\n            Callback = function(value)\n                NexusState.favorites.autoEnabled = value\n                if value then\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusState.favorites.thread = task.spawn(function()\n                        local favoriteEvent = Events:FindFirstChild("FavoriteItem")\n                        if not favoriteEvent then\n                            NexusLib:Notify({ Title = "Auto Favourite", Message = "FavoriteItem remote not found!", Duration = 3 })\n                            NexusState.favorites.autoEnabled = false\n                            if autoFavToggle and type(autoFavToggle.SetValue) == "function" then\n                                autoFavToggle:SetValue(false)\n                            end\n                            return\n                        end\n                        while NexusState.favorites.autoEnabled do\n                            pcall(function()\n                                local userId = LocalPlayer.UserId\n                                local userData = Data:FindFirstChild(tostring(userId))\n                                if not userData then return end\n                                local inventory = userData:FindFirstChild("Inventory")\n                                if not inventory then return end\n                                local selected = NexusState.favorites.selectedFish or {}\n                                if #selected == 0 then return end\n                                local selectedSet = {}\n                                for _, name in ipairs(selected) do selectedSet[name] = true end\n                                for _, item in pairs(inventory:GetChildren()) do\n                                    local fullName = item.Name\n                                    if not string.find(fullName, "| Favorite$") then\n                                        local fishName = fullName:match("^(.-)%s*|") or fullName\n                                        if selectedSet[fishName] then\n                                            favoriteEvent:FireServer(fullName)\n                                        end\n                                    end\n                                end\n                            end)\n                            task.wait(0.3)\n                        end\n                    end)\n                    NexusLib:Notify({ Title = "Auto Favourite", Message = "Enabled - scanning every 0.3s", Duration = 2 })\n                else\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusLib:Notify({ Title = "Auto Favourite", Message = "Disabled", Duration = 2 })\n                end\n            end\n        })\n    end\n    -- ===== AUTO PRAY SPIRIT =====\n    do\n        local PraySection = FarmingTab:CreateSection("Auto Pray Spirit")\n        local prayEnabled = false\n        local prayThread = nil\n        local prayConnections = {}\n        local lastInteractTime = 0\n        local cooldown = 2 -- seconds between interactions\n\n        -- Scan and handle spirits\n        local function scanAndPray()\n            local godFolder = workspace:FindFirstChild("NPC") and workspace.NPC:FindFirstChild("God")\n            if not godFolder then return end\n\n            local now = tick()\n            if now - lastInteractTime < cooldown then return end\n\n            -- Find every model in the God folder (sub-models included)\n            local models = {}\n            for _, child in ipairs(godFolder:GetDescendants()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Model") then\n                    table.insert(models, child)\n                end\n            end\n\n            for _, model in ipairs(models) do\n                -- Find HumanoidRootPart or PrimaryPart\n                local hrp = model:FindFirstChild("HumanoidRootPart")\n                if not hrp then\n                    hrp = model.PrimaryPart\n                end\n                if hrp then\n                -- Find Talk and ProximityPrompt\n                local talk = hrp:FindFirstChild("Talk")\n                if talk then\n                local prompt = talk:FindFirstChild("ProximityPrompt")\n                if prompt then\n                -- Configure ProximityPrompt\n                pcall(function()\n                    prompt.RequiresLineOfSight = false\n                    prompt.HoldDuration = 0\n                end)\n\n                -- Teleport to the spirit position\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild("HumanoidRootPart")\n                    if root then\n                        root.CFrame = hrp.CFrame + Vector3.new(0, 2, 0)\n                    end\n                end\n\n                -- Trigger ProximityPrompt\n                local success = false\n                -- Cach 1: Fire Proximity Prompt\n                if fireproximityprompt and prompt then\n                    pcall(function()\n                        fireproximityprompt(prompt)\n                        success = true\n                    end)\n                end\n                -- Method 2: firesignal\n                if firesignal and prompt then\n                    pcall(function()\n                        firesignal(prompt.PromptButtonHoldBegan)\n                        task.wait(0.1)\n                        firesignal(prompt.PromptButtonHoldEnded)\n                        success = true\n                    end)\n                end\n                -- Method 2: use VirtualInputManager to press E\n                if not success then\n                    pcall(function()\n                        local vim = game:GetService("VirtualInputManager")\n                        if vim then\n                            vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)\n                            task.wait(0.1)\n                            vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)\n                            success = true\n                        end\n                    end)\n                end\n                -- Method 3: use VirtualUser (last fallback)\n                if not success then\n                    pcall(function()\n                        if VirtualUser then\n                            VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                            task.wait(0.1)\n                            VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                            success = true\n                        end\n                    end)\n                end\n\n                if success then\n                    lastInteractTime = now\n                    NexusLib:Notify({ Title = "Pray", Message = "Prayed to " .. model.Name, Duration = 2 })\n                    break -- only interact with one spirit per pass\n                end\n                end\n                end\n                end\n            end\n        end\n\n        -- Start helper\n        local function startPray()\n            if prayEnabled then return end\n            prayEnabled = true\n            prayThread = task.spawn(function()\n                while prayEnabled do\n                    pcall(scanAndPray)\n                    task.wait(1.5) -- scan every 1.5 seconds\n                end\n            end)\n            NexusLib:Notify({ Title = "Auto Pray", Message = "Enabled", Duration = 2 })\n        end\n\n        local function stopPray()\n            prayEnabled = false\n            if prayThread then\n                task.cancel(prayThread)\n                prayThread = nil\n            end\n            for _, conn in ipairs(prayConnections) do\n                pcall(function() conn:Disconnect() end)\n            end\n            prayConnections = {}\n            NexusLib:Notify({ Title = "Auto Pray", Message = "Disabled", Duration = 2 })\n        end\n\n        -- Toggle\n        Cfg.register(PraySection:CreateToggle(Cfg.wrap("Toggle", "Auto Teleport + Interact (Pray) Spirit", {\n            Name = "Auto Teleport + Interact (Pray) Spirit",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startPray()\n                else\n                    stopPray()\n                end\n            end\n        })), "Toggle", "Auto Teleport + Interact (Pray) Spirit", {\n            Name = "Auto Teleport + Interact (Pray) Spirit",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startPray()\n                else\n                    stopPray()\n                end\n            end\n        })\n    end\n\nend\n\n-- ============================================================\n-- ===== SHOP TAB =====\n-- ============================================================\ndo\n    local ShopTab = Window:CreateTab("Shop")\n\n    -- Index\n    do\n        local IndexSection = ShopTab:CreateSection("Index")\n        IndexSection:CreateButton({\n            Name = "Unlock all fish",\n            Callback = function()\n                local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                if not userData then\n                    NexusLib:Notify({ Title = "Index", Message = "User data not found!", Duration = 2 })\n                    return\n                end\n                local indexFolder = userData:FindFirstChild("Index")\n                if not indexFolder then\n                    NexusLib:Notify({ Title = "Index", Message = "Index folder not found!", Duration = 2 })\n                    return\n                end\n                local count = 0\n                for _, child in ipairs(indexFolder:GetChildren()) do\n                    if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("NumberValue") or child:IsA("IntValue") then\n                        child.Value = 1\n                        count = count + 1\n                    elseif typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("BoolValue") then\n                        child.Value = true\n                        count = count + 1\n                    end\n                end\n            end\n        })\n    end\n\n    -- Upgrade Skill\n    do\n        local UpgradeSkillSection = ShopTab:CreateSection("Upgrade Skill")\n        local function GetOwnedSkills()\n            local userId = LocalPlayer and LocalPlayer.UserId\n            if not userId then return {} end\n            local userData = Data and Data:FindFirstChild(tostring(userId))\n            if not userData then return {} end\n            local skillFolder = userData:FindFirstChild("Skill")\n            if not skillFolder then return {} end\n            local ownedSkills = {}\n            for _, child in pairs(skillFolder:GetChildren()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then\n                    local owned = child:FindFirstChild("Owned")\n                    if typeof(owned) == "Instance" and owned:IsA("BoolValue") and owned.Value == true then\n                        table.insert(ownedSkills, child.Name)\n                    end\n                end\n            end\n            return ownedSkills\n        end\n\n        local skillOptions = GetOwnedSkills()\n        if #skillOptions == 0 then skillOptions = {"No skill owned"} end\n        local selectedSkill = skillOptions[1] or "No skill owned"\n\n        local skillDropdown = Cfg.register(UpgradeSkillSection:CreateDropdown(Cfg.wrap("Dropdown", "Choose A Skill That Needs To Upgrade", {\n            Name = "Choose A Skill That Needs To Upgrade",\n            Options = skillOptions,\n            Default = selectedSkill,\n            Callback = function(value) selectedSkill = value end\n        })), "Dropdown", "Choose A Skill That Needs To Upgrade", {\n            Name = "Choose A Skill That Needs To Upgrade",\n            Options = skillOptions,\n            Default = selectedSkill,\n            Callback = function(value) selectedSkill = value end\n        })\n\n        local upgradeSkillMethodDropdown = Cfg.register(UpgradeSkillSection:CreateDropdown(Cfg.wrap("Dropdown", "Upgrade Method", {\n            Name = "Upgrade Method",\n            Options = {"Instant", "Teleport"},\n            Default = NexusState.upgradeSkill.method or "Instant",\n            Callback = function(value) NexusState.upgradeSkill.method = value end\n        })), "Dropdown", "Upgrade Method", {\n            Name = "Upgrade Method",\n            Options = {"Instant", "Teleport"},\n            Default = NexusState.upgradeSkill.method or "Instant",\n            Callback = function(value) NexusState.upgradeSkill.method = value end\n        })\n\n        UpgradeSkillSection:CreateButton({\n            Name = "Upgrade Selected Skill",\n            Callback = function()\n                if selectedSkill == "No skill owned" or not selectedSkill then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "No skill selected!", Duration = 2 })\n                    return\n                end\n                local userId = LocalPlayer and LocalPlayer.UserId\n                if not userId then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "Player not ready!", Duration = 2 })\n                    return\n                end\n                local userData = Data and Data:FindFirstChild(tostring(userId))\n                if not userData then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "User data not found!", Duration = 2 })\n                    return\n                end\n                local essenceOrb = userData:FindFirstChild("EssenceOrb")\n                if not essenceOrb or not (typeof(essenceOrb) == "Instance" and essenceOrb:IsA("NumberValue")) then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "EssenceOrb not found!", Duration = 2 })\n                    return\n                end\n                if essenceOrb.Value <= 0 then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "Not enough EssenceOrb!", Duration = 2 })\n                    return\n                end\n                if not Events or not Events.UpgradeSkill then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "UpgradeSkill remote not found!", Duration = 2 })\n                    return\n                end\n\n                NexusState.upgradeSkill.teleported = false\n                NexusState.upgradeSkill.oldPosition = nil\n                if NexusState.upgradeSkill.method == "Teleport" then\n                    local npc = Workspace:FindFirstChild("NPC")\n                    if npc then\n                        local func = npc:FindFirstChild("Function")\n                        if func then\n                            local zengTianguo = func:FindFirstChild("Zeng Tianguo")\n                            if typeof(zengTianguo) == "Instance" and zengTianguo:IsA("Model") then\n                                local hrp = zengTianguo:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            NexusState.upgradeSkill.oldPosition = root.Position\n                              , cframe = CFrame.new(-297, 9, 12), power = 0},\n        {name = "Island 2", cframe = CFrame.new(-1274, 21, -270), power = 17},\n        {name = "Island 3", cframe = CFrame.new(57, 9, 1115), power = 28},\n        {name = "Island 4", cframe = CFrame.new(-1343, 9, 1083), power = 35},\n        {name = "Island 5", cframe = CFrame.new(-12, 9, -1696), power = 45},\n        {name = "Island 6", cframe = CFrame.new(-1184, 20, -1652), power = 55},\n        {name = "Island 7", cframe = CFrame.new(1470, 9, -1685), power = 62},\n        {name = "Island 8", cframe = CFrame.new(1130, 9, 1364), power = 72},\n        {name = "Island 9", cframe = CFrame.new(1459, 8, -248), power = 90},\n        {name = "Island 10", cframe = CFrame.new(3028, 16, -124), power = 100},\n        -- Island 11 (if u have ego and tiger): chi duoc recommend khi co ca rod Ego va Tiger\n        {name = "Island 11", cframe = CFrame.new(-2498.64966, 9.27561855, -215.078888, 0.444082469, 1.84874409e-08, -0.895985901, -3.89493522e-08, 1, 1.32894518e-09, 0.895985901, 3.43079094e-08, 0.444082469), power = 110},\n        {name = "Island 12", cframe = CFrame.new(-2912.0498, 6.76233578, 1200.33838, 0.272515684, -2.71757763e-08, 0.962151349, -1.71733454e-08, 1, 3.31089112e-08, -0.962151349, -2.55460559e-08, 0.272515684), power = 120},\n        {name = "Island 13", cframe = CFrame.new(-2690.31543, 6.76233625, -1313.08179, -0.539970279, 1.03704998e-07, 0.841684103, 7.36837009e-08, 1, -7.59405978e-08, -0.841684103, 2.10127347e-08, -0.539970279), power = 130},\n    },\n    Reroll = { method = "Instant", teleported = false, oldPosition = nil, running = false, thread = nil },\n    buyRod = { method = "Instant", teleported = false, oldPosition = nil },\n    learnSkill = { method = "Instant", teleported = false, oldPosition = nil },\n    upgradeSkill = { method = "Instant", teleported = false, oldPosition = nil },\n    exchange = { method = "Instant", teleported = false, oldPosition = nil },\n    upgradeCharacter = { method = "Instant", teleported = false, oldPosition = nil },\n    favorites = { selectedFish = {}, autoEnabled = false, thread = nil },\n    AutoFarm = {\n        enabled = false,\n        selectedIsland = nil,\n        filter1 = nil,\n        filter2 = nil,\n        targetFishName = "",\n        teleported = false,\n        thread = nil,\n    },\n    LastMaoshan = false,\n    LastTaoist = false,\n    LastSpirit = false,\n    LastWeather = nil,\n    reportedJobId = game.JobId,\n    autoRecommendRunning = false,\n    autoRecommendThread = nil,\n    autoRebirthRunning = false,\n    autoRebirthThread = nil,\n    autoCraftRunning = false,\n    autoCraftThread = nil,\n    autoGachaRunning = false,\n    autoGachaThread = nil,\n    autoDoRunning = false,\n    autoDoThread = nil,\n    autoClaimRunning = false,\n    autoClaimThread = nil,\n    ticketTargetCount = 0,\n    ticketCurrentCount = 0,\n    ticketQuestActive = false,\n    ticketQuestClaimed = false,\n    savedRoutineFlags = nil,\n    craftBaitQuantity = 1,\n    craftBaitName = "Rainbow Bait",\n    selectedBait = nil,\n    buyBaitQuantity = 10,\n    buyBaitThreshold = 5,\n    selectedOptions = {"Cash", "Level"},\n    UpgradeCharacter = nil,\n    flying = false,\n    flySpeed = 50,\n    bg = nil,\n    bv = nil,\n    flyInputConnection = nil,\n    flyInputEndConnection = nil,\n    flyKeys = { Up = false, Down = false },\n    waterY = nil,\n    waterPart = nil,\n    waterPartsList = {},\n    waterWalkConnection = nil,\n    waterWalkEnabled = false,\n    BossKeywords = { "boss", "raid", "giant", "king", "lord" },\n    SecretBossKeywords = { "secret", "hidden", "mythic", "event", "rare" },\n    BossNameSet = {},\n    SecretBossNameSet = {},\n    autoCraftRodRunning = false,\n    autoCraftRodThread = nil,\n    enzoHitIndex = 0,\n    enzoPhaseActive = false,\n    enzoNextClick = 0,\n    fullBrightApplied = false,\n    enzoPrevP = nil,\n    enzoDir = 0,\n    enzoArmed = true,\n    autoGachaToggleRef = nil,\n    sellMethod1 = "Spam",\n    sellMethod2 = "Instant",\n    lastPosition = nil,\n    sellCooldown = 0,\n    craftRodMethod = "Instant",\n    lastCraftPosition = nil,\n    craftBaitMethod = "Instant",\n    buyBaitMethod = "Instant",\n    lastCraftBaitPosition = nil,\n    lastBuyBaitPosition = nil,\n    spectateToggle = false,\n    notificationsEnabled = true,\n    fakeNameEnabled = false,\n    fakeName = "NexusPlayer",\n    fakeDisplayName = "NexusPlayer",\n    fakeUserId = "0",\n    fakeIdMode = 1,\n    -- Guild display (neu game hien ten guild canh ten player -> doi ten guild\n    -- de khong bi report/ban). realGuildName="" thi bo qua.\n    realGuildName = "",\n    fakeGuildName = "NexusGuild",\n    antiReportEnabled = true,\n    currentLanguage = "auto",\n    skillSeqIndex = 1,\n    lastSkillCastTime = 0,\n    SmartWeather = {\n        enabled = false,\n        selectedIslands = {\n            ["Island 2"] = true,\n            ["Island 3"] = true,\n            ["Island 5"] = true,\n            ["Island 6"] = true,\n            ["Island 7"] = true,\n            ["Island 8"] = true,\n        },\n        activeOverride = false,\n        savedCFrame = nil,\n        savedFlags = nil,\n        targetIsland = nil,\n    },\n    questFarmingIsland = "Auto (Recommend)",\n    isDoingUseBaitQuest = false,\n}\ndo\n    -- Override NexusLib.Notify de kiem tra toggle va ho tro ca method (:) lan direct (.)\n    if NexusLib and NexusLib.Notify then\n        local originalNotify = NexusLib.Notify\n        NexusLib.Notify = function(selfOrConfig, maybeConfig)\n            if NexusState and NexusState.notificationsEnabled == false then\n                return\n            end\n            local config = maybeConfig\n            if not config and type(selfOrConfig) == "table" then\n                if selfOrConfig.Title or selfOrConfig.Message or selfOrConfig.Duration then\n                    config = selfOrConfig\n                end\n            end\n            config = config or {}\n\n            pcall(function()\n                originalNotify(NexusLib, config)\n            end)\n        end\n    end\nend\n\n-- ============================================================\n-- ===== NEXUS USERS PROTECTION (ANTI-REPORT) =====\n-- ============================================================\ndo\n    pcall(function()\n        LocalPlayer:SetAttribute("NexusUser", true)\n        if LocalPlayer.Character then\n            LocalPlayer.Character:SetAttribute("NexusUser", true)\n        end\n        LocalPlayer.CharacterAdded:Connect(function(char)\n            pcall(function()\n                LocalPlayer:SetAttribute("NexusUser", true)\n                char:SetAttribute("NexusUser", true)\n            end)\n        end)\n    end)\n\n    pcall(function()\n        if hookmetamethod and not _G.NexusNamecallHooked then\n            _G.NexusNamecallHooked = true\n            local oldNamecall\n            oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)\n                local method = getnamecallmethod()\n                if (method == "ReportAbuse" or method == "reportAbuse") and self == Players then\n                    local args = {...}\n                    local target = args[1]\n                    local isNexusUser = false\n                    if typeof and typeof(target) == "Instance" then\n                        if typeof(target) == "Instance" and typeof(target) == "Instance" and target:IsA("Player") then\n                            if target:GetAttribute("NexusUser") or (target.Character and target.Character:GetAttribute("NexusUser")) then\n                                isNexusUser = true\n                            end\n                        end\n                    elseif type(target) == "string" then\n                        local p = Players:FindFirstChild(target)\n                        if p and (p:GetAttribute("NexusUser") or (p.Character and p.Character:GetAttribute("NexusUser"))) then\n                            isNexusUser = true\n                        end\n                    end\n                    if isNexusUser and NexusState.antiReportEnabled ~= false then\n                        NexusLib:Notify({\n                            Title = "Nexus Shield",\n                            Message = "You cannot report another Nexus Hub user!",\n                            Duration = 3\n                        })\n                        return nil\n                    end\n                end\n                return oldNamecall(self, ...)\n            end)\n        end\n    end)\nend\n\n-- ============================================================\n-- ===== AUTO LANGUAGE (I18N) =====\n-- ============================================================\nlocal I18n = {}\ndo\n    local LocalizationService = Services.LocalizationService or game:GetService("LocalizationService")\n    local rawLocale = "en"\n    pcall(function()\n        rawLocale = string.lower(\n            LocalizationService.RobloxLocaleId \n            or LocalizationService.SystemLocaleId \n            or (LocalizationService.GetRobloxLocaleId and LocalizationService:GetRobloxLocaleId()) \n            or (LocalizationService.GetSystemLocaleId and LocalizationService:GetSystemLocaleId()) \n            or "en"\n        )\n    end)\n\n    local autoLang = "en"\n    if string.find(rawLocale, "^th") then\n        autoLang = "th"\n    elseif string.find(rawLocale, "^id") then\n        autoLang = "id"\n    elseif string.find(rawLocale, "^es") then\n        autoLang = "es"\n    elseif string.find(rawLocale, "^pt") then\n        autoLang = "pt"\n    elseif string.find(rawLocale, "^zh") then\n        autoLang = "zh"\n    elseif string.find(rawLocale, "^ru") then\n        autoLang = "ru"\n    end\n\n    NexusState.detectedLanguage = autoLang\n\n    local DICTIONARY = {\n        es = {\n            ["Session"] = "Sesi\u{F3}n",\n            ["Routine"] = "Pesca",\n            ["Shop"] = "Tienda",\n            ["Exchange"] = "Intercambio",\n            ["Quests"] = "Misiones",\n            ["Upgrade"] = "Mejoras",\n            ["Teleport"] = "Teletransporte",\n            ["Settings"] = "Ajustes",\n            ["Session overview"] = "Resumen de la sesi\u{F3}n",\n            ["Release notes"] = "Notas de la versi\u{F3}n",\n            ["Fishing routine"] = "Rutina de pesca",\n            ["Farm On Weather Section"] = "Auto Farm por Clima",\n            ["Skill profile"] = "Perfil de habilidades",\n            ["Auto Equip"] = "Auto Equipar",\n            ["Auto Nameless Octoparasite"] = "Auto Pulpo Sin Nombre",\n            ["Auto Favorite Fish"] = "Auto Favorito de Peces",\n            ["Auto Pray Spirit"] = "Auto Rezar al Esp\u{ED}ritu",\n            ["Auto Farm"] = "Auto Farm",\n            ["Index"] = "\u{CD}ndice de Peces",\n            ["Upgrade Skill"] = "Mejorar Habilidad",\n            ["Craft Rod"] = "Fabricar Ca\u{F1}a",\n            ["Auto Buy Bait"] = "Auto Comprar Cebo",\n            ["Auto Buy Rod"] = "Auto Comprar Ca\u{F1}a",\n            ["Learn Skills"] = "Aprender Habilidades",\n            ["Trait Reroll"] = "Reroll de Rasgos",\n            ["Craft Bait"] = "Fabricar Cebo",\n            ["Auto Gacha"] = "Auto Gacha",\n            ["Exchange Items"] = "Intercambiar Objetos",\n            ["Auto Claim Ticket Quest"] = "Auto Reclamar Misi\u{F3}n Ticket",\n            ["Daily Quests"] = "Misiones Diarias",\n            ["Material Farming"] = "Farm de Materiales",\n            ["Auto Do Ticket Quest"] = "Auto Hacer Misi\u{F3}n Ticket",\n            ["Character Upgrade"] = "Mejorar Personaje",\n            ["Character"] = "Personaje",\n            ["World & Misc"] = "Mundo y Varios",\n            ["Streamer Mode (Fake Name)"] = "Modo Streamer (Nombre Falso)",\n            ["Language & Localization"] = "Idioma y Localizaci\u{F3}n",\n            ["Nexus Shield"] = "Escudo Nexus",\n            ["Staff Watch"] = "Vigilancia de Staff",\n            ["ESP"] = "ESP",\n            ["Lock catch bar"] = "Bloquear barra de captura",\n            ["Auto Cil\n    end\n\n    local scanQueued = false\n\n    local function collectNpcModels()\n        local out = {}\n        local npcFolder = Workspace:FindFirstChild("NPC")\n        if npcFolder then\n            for _, sub in ipairs(npcFolder:GetChildren()) do\n                out[#out + 1] = sub\n                for _, m in ipairs(sub:GetChildren()) do\n                    out[#out + 1] = m\n                end\n            end\n        end\n        return out\n    end\n\n    local function runNpcScan()\n        if game.JobId ~= NexusState.reportedJobId then\n            NexusState.reportedJobId = game.JobId\n            NexusState.LastMaoshan = false\n            NexusState.LastTaoist = false\n            NexusState.LastSpirit = false\n            NexusState.LastWeather = nil\n        end\n\n        local npcScan = (ScanMaoshan or ScanTaoist) and collectNpcModels() or {}\n\n        if ScanMaoshan then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == "Instance" and v:IsA("Model") and (string.find(v.Name:lower(), "maoshan") or string.find(v.Name:lower(), "merchant")) and v:FindFirstChild("HumanoidRootPart") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastMaoshan then\n                NexusState.LastMaoshan = true\n                sendDiscordWebhook(MAOSHAN_WEBHOOK, "Maoshan NPC")\n            elseif not found then\n                NexusState.LastMaoshan = false\n            end\n        end\n\n        if ScanTaoist then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == "Instance" and v:IsA("Model") and string.find(v.Name:lower(), "taoist") and v:FindFirstChild("HumanoidRootPart") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastTaoist then\n                NexusState.LastTaoist = true\n                sendDiscordWebhook(TAOIST_WEBHOOK, "Taoist NPC")\n            elseif not found then\n                NexusState.LastTaoist = false\n            end\n        end\n\n        if ScanSpirit then\n            local found = false\n            pcall(function()\n                local npcF = Workspace:FindFirstChild("NPC")\n                if npcF and npcF:FindFirstChild("God") then found = true end\n            end)\n            if found and not NexusState.LastSpirit then\n                NexusState.LastSpirit = true\n                sendSpiritWebhook()\n            elseif not found then\n                NexusState.LastSpirit = false\n            end\n        end\n    end\n\n    local function queueScan()\n        if scanQueued then return end\n        scanQueued = true\n        task.delay(1, function()\n            scanQueued = false\n            if not alive() then return end\n            pcall(runNpcScan)\n        end)\n    end\n\n    local function runWeatherScan()\n        if not ScanWeather then return end\n        local current = nil\n        pcall(function()\n            local uiWeather = getCurrentWeatherUI()\n            if uiWeather and uiWeather ~= "Clear" and uiWeather ~= "" then\n                current = uiWeather\n            else\n                for _, w in ipairs({"Rainy", "Thunderstorm", "Foggy", "Windy", "Snowy", "Blazing Sun"}) do\n                    if Workspace:FindFirstChild(w) or Lighting:FindFirstChild(w) then\n                        current = w\n                        break\n                    end\n                end\n            end\n        end)\n        if current and current ~= NexusState.LastWeather and current:lower() ~= "clear" then\n            NexusState.LastWeather = current\n            sendWeatherWebhook(WEATHER_WEBHOOK, current)\n        end\n    end\n\n    task.spawn(function()\n        local npcFolder = Workspace:WaitForChild("NPC", 30)\n        if npcFolder then\n            npcFolder.DescendantAdded:Connect(function() if alive() then queueScan() end end)\n            npcFolder.DescendantRemoving:Connect(function() if alive() then queueScan() end end)\n        end\n\n        pcall(function()\n            local mg = LocalPlayer:WaitForChild("PlayerGui", 30):WaitForChild("MainGui", 30)\n            local info = mg and mg:WaitForChild("Info", 15)\n            local infoFrame = info and info:WaitForChild("Info", 15)\n            local weatherFrame = infoFrame and infoFrame:WaitForChild("Weather", 15)\n            local val = weatherFrame and weatherFrame:WaitForChild("Value", 15)\n            if val and typeof(val) == "Instance" then\n                local signal = (typeof(val) == "Instance" and val:IsA("TextLabel") and val:GetPropertyChangedSignal)("Text") or val:GetPropertyChangedSignal("Value")\n                signal:Connect(function() if alive() then runWeatherScan() end end)\n            end\n        end)\n\n        task.wait(2)\n        if alive() then\n            pcall(runNpcScan)\n            pcall(runWeatherScan)\n        end\n    end)\n]]\n\n-- ============================================================\n-- ===== MAIN LOOPS (Boss Farm, Auto Sell, GUI QTE) =====\n-- ============================================================\nlocal function GetInventoryLimit()\n    local userFolder = GetPlayerData()\n    if not userFolder then return 0 end\n    local sum = 0\n    pcall(function()\n        for _, v in pairs(userFolder.Inventory:GetChildren()) do sum = sum + 1 end\n        for _, v in pairs(userFolder.Hotbar:GetChildren()) do sum = sum + v.Quantity.Value end\n    end)\n    return sum\nend\n\nlocal function IsInventoryFull()\n    local userFolder = GetPlayerData()\n    if not userFolder then return false end\n    local limit = 0\n    pcall(function() limit = userFolder.InventoryLimit.Value end)\n    return GetInventoryLimit() >= limit\nend\n\nlocal GuiService = Services.GuiService\nlocal nexusPanel = LocalPlayer.PlayerGui:FindFirstChild("NexusPanel")\n\nlocal function DisableNexusKeyboardActivation(object)\n    if typeof(object) == "Instance" and object:IsA("GuiObject") then\n        object.Selectable = false\n    end\nend\n\nif runtimeEnv.NexusSpaceGuardConnection then\n    runtimeEnv.NexusSpaceGuardConnection:Disconnect()\n    runtimeEnv.NexusSpaceGuardConnection = nil\nend\nif runtimeEnv.NexusSelectableGuardConnection then\n    runtimeEnv.NexusSelectableGuardConnection:Disconnect()\n    runtimeEnv.NexusSelectableGuardConnection = nil\nend\n\nif nexusPanel then\n    DisableNexusKeyboardActivation(nexusPanel)\n    for _, object in ipairs(nexusPanel:GetDescendants()) do\n        DisableNexusKeyboardActivation(object)\n    end\n    runtimeEnv.NexusSelectableGuardConnection = nexusPanel.DescendantAdded:Connect(function(object)\n        task.defer(DisableNexusKeyboardActivation, object)\n    end)\nend\n\nruntimeEnv.NexusSpaceGuardConnection = UserInputService.InputBegan:Connect(function(input)\n    if input.KeyCode == Enum.KeyCode.Space then\n        local selected = GuiService.SelectedObject\n        if selected and nexusPanel and selected:IsDescendantOf(nexusPanel) then\n            GuiService.SelectedObject = nil\n        end\n    end\nend)\n\nlocal function bossFarmEnabled()\n    return Fishing.Flags.AutoFarmBoss or Fishing.Flags.AutoFarmSecretBoss\nend\n\nlocal function loadBossNameSets()\n    for k in pairs(NexusState.BossNameSet) do NexusState.BossNameSet[k] = nil end\n    for k in pairs(NexusState.SecretBossNameSet) do NexusState.SecretBossNameSet[k] = nil end\n    local infoFolder = ReplicatedStorage:FindFirstChild("Info")\n    if not infoFolder then return end\n    pcall(function()\n        local areaRarity = infoFolder:FindFirstChild("FishingAreaRarity")\n        if areaRarity then\n            local rarityData = require(areaRarity)\n            if type(rarityData) == "table" and type(rarityData["Secret Boss"]) == "table" then\n                for fishName in pairs(rarityData["Secret Boss"]) do\n                    local name = string.lower(tostring(fishName))\n                    NexusState.SecretBossNameSet[name] = true\n                    NexusState.BossNameSet[name] = true\n                end\n            end\n        end\n    end)\n    pcall(function()\n        local inventory = infoFolder:FindFirstChild("Inventory")\n        if inventory then\n            for _, module in pairs(inventory:GetChildren()) do\n                if typeof(module) == "Instance" and typeof(module) == "Instance" and module:IsA("ModuleScript") then\n                    local ok, itemData = pcall(require, module)\n                    if ok and type(itemData) == "table" then\n                        local name = string.lower(tostring(itemData.FishName or module.Name))\n                        if itemData.Boss == true or itemData.SpecialBoss == true or itemData.SecretBoss == true then\n                            NexusState.BossNameSet[name] = true\n                        end\n                        if itemData.SecretBoss == true then\n                            NexusState.SecretBossNameSet[name] = true\n                        end\n                    end\n                end\n            end\n        end\n    end)\nend\n-- Defer heavy boss-name scan until after boot so opening the hub stays smooth\ntask.spawn(function()\n    task.wait(3)\n    if not alive() then return end\n    pcall(loadBossNameSets)\nend)\n\nlocal function textHasKeyword(text, keywords)\n    text = string.lower(tostring(text or ""))\n    for _, keyword in ipairs(keywords) do\n        if string.find(text, keyword, 1, true) then return true end\n    end\n    return false\nend\n\nlocal function getCurrentHookTarget()\n    local target = Fishing.BossFarm.CurrentTarget\n    local info = { Name = nil, Data = nil, Instance = nil, Boss = false, SecretBoss = false }\n    if type(target) == "table" then\n        info.Data = target\n        info.Name = target.FishName or target.Name or target.fishName\n        info.Boss = target.Boss == true or target.SpecialBoss == true or target.SecretBoss == true\n        info.SecretBoss = target.SecretBoss == true\n    elseif typeof and typeof(target) == "Instance" then\n        info.Instance = target\n        info.Name = target:GetAttribute("FishName") or target.Name\n        info.Boss = target:GetAttribute("Boss") == true or target:GetAttribute("SpecialBoss") == true or target:GetAttribute("SecretBoss") == true\n        info.SecretBoss = target:GetAttribute("SecretBoss") == true\n    elseif type(target) == "string" then\n        info.Name = target\n    end\n    local fishId = LocalPlayer:GetAttribute("FishID")\n    local fishes = Workspace:FindFirstChild("Fishes")\n    local fishInstance = fishId and fishes and fishes:FindFirstChild(tostring(fishId))\n    if fishInstance then\n        info.Instance = fishInstance\n        info.Name = info.Name or fishInstance:GetAttribute("FishName") or fishInstance.Name\n        info.Boss = info.Boss or fishInstance:GetAttribute("Boss") == true or fishInstance:GetAttribute("SpecialBoss") == true or fishInstance:GetAttribute("SecretBoss") == true\n        info.SecretBoss = info.SecretBoss or fishInstance:GetAttribute("SecretBoss") == true\n    end\n    local fishingGui = MainGui:FindFirstChild("Fishing")\n    local progression = fishingGui and fishingGui:FindFirstChild("ProgressionBar")\n    local fishNameLabel = progression and progression:FindFirstChild("FishName")\n    if (not info.Name or info.Name == "" or info.Name == "???") and fishNameLabel and fishNameLabel.Text ~= "" then\n        info.Name = fishNameLabel.Text\n    end\n    return info\nend\n\nlocal function isSecretBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    local name = string.lower(tostring(current.Name or ""))\n    return current.SecretBoss or NexusState.olorShift_Top = Color3.new(1,1,1)\n            Lighting.Brightness = 2\n            Lighting.OutdoorAmbient = Color3.new(1,1,1)\n            NexusState.fullBrightApplied = true\n        end\n    else\n        if NexusState.fullBrightApplied then\n            NexusState.fullBrightApplied = false\n        end\n    end\nend\n\nruntimeEnv.NexusFrameConnection = RunService.RenderStepped:Connect(function(dt)\n    if not alive() then return end\n    pcall(updateFrameLogic, dt)\nend)\n\n-- ============================================================\n-- ===== PREPARE GLOBALS FOR THE CHUNKS =====\n-- ============================================================\n_G.RunService = RunService\n_G.LocalPlayer = LocalPlayer\n_G.VirtualUser = VirtualUser\n_G.UserInputService = UserInputService\n_G.Events = Events\n_G.MiscFlags = MiscFlags\n_G.alive = alive\n_G.runtimeEnv = runtimeEnv\n_G.Players = Players\n_G.Workspace = Workspace\n_G.Lighting = Lighting\n_G.NexusState = NexusState\n_G.Fishing = Fishing\n\n-- ===== LIVE ANTI-AFK (main chunk; fires only on real Idled, never steals controller) =====\ndo\n    local function nexusNudgeInput()\n        if Fishing and Fishing.Flags and not Fishing.Flags.AntiAFK then return end\n        local moving = false\n        pcall(function()\n            local char = LocalPlayer.Character\n            local hum = char and char:FindFirstChildOfClass("Humanoid")\n            local md = hum and hum.MoveDirection\n            if md and (math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05) then moving = true end\n        end)\n        if moving then return end\n        pcall(function()\n            if Events and Events:FindFirstChild("AFK") then\n                Events.AFK:FireServer()\n            end\n            if VirtualUser and workspace.CurrentCamera then\n                VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                task.wait(0.2)\n                VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n            end\n        end)\n    end\n    pcall(function()\n        if runtimeEnv.AntiAFKConnection then runtimeEnv.AntiAFKConnection:Disconnect() end\n    end)\n    runtimeEnv.AntiAFKConnection = LocalPlayer.Idled:Connect(function()\n        nexusNudgeInput()\n    end)\nend\n\n-- ===== RUN THE EXTRA CHUNKS =====\nif _G.codetorun then loadstring(_G.codetorun)() end\nif _G.codes then loadstring(_G.codes)() end\n\npcall(function()\n    if I18n and I18n.initListeners then\n        I18n.initListeners()\n        I18n.applyLanguage()\n    end\nend)\n\n\nruntimeEnv.AutoFarm = true\n\n-- ===== BOOT XONG =====\npcall(function()\n    if runtimeEnv.NexusBoot then\n        runtimeEnv.NexusBoot.stage = "xong"\n        runtimeEnv.NexusBoot.done = true\n    end\n    if runtimeEnv.NexusBootGui then runtimeEnv.NexusBootGui:Destroy() end\nend)\n',
