n) ..\n                    "\\n\\nExecute source truc tiep da bi KHOA. Phai dung loader hwfnew de vao.")\n            end\n        end)\n        LP:Kick("Nexus: " .. tostring(reason))\n    end\n\n    -- ================== B\xE1\xBA\xA2O V\xE1\xBB\x86 TOKEN HANDOFF CH\xE1\xBB\x90NG BYPASS ==================\n    -- Ch\xE1\xBB\x91ng tr\xC3\xB2 bypass g\xC3\xB5: getgenv().NexusPremiumVerified = true\n    -- B\xE1\xBA\xAFt bu\xE1\xBB\x99c ph\xE1\xBA\xA3i c\xC3\xB3 Server Nonce h\xE1\xBB\xA3p l\xE1\xBB\x87 t\xE1\xBB\xAB Loader v\xE1\xBB\xABa g\xE1\xBB\xADi sang v\xC3\xA0 ti\xC3\xAAu th\xE1\xBB\xA5 ngay (One-time token).\n    local serverNonce = _rt.NexusGuardNonce\n    _rt.NexusGuardNonce = nil -- Ti\xC3\xAAu th\xE1\xBB\xA5 ngay l\xE1\xBA\xADp t\xE1\xBB\xA9c token d\xC3\xB9ng 1 l\xE1\xBA\xA7n\n\n    local isValidHandoff = false\n    if type(serverNonce) == "string" and #serverNonce >= 8 then\n        -- C\xC3\xB3 server token t\xE1\xBB\xAB loader g\xE1\xBB\xADi qua -> h\xE1\xBB\xA3p l\xE1\xBB\x87\n        isValidHandoff = true\n    elseif (_rt.NexusPremiumVerified == true or _rt.NexusFreemiumVerified == true) and type(_rt.Key) == "string" and #_rt.Key >= 6 then\n        -- Fallback tr\xC6\xB0\xE1\xBB\x9Dng h\xE1\xBB\xA3p loader c\xC5\xA9 nh\xC6\xB0ng ph\xE1\xBA\xA3i k\xC3\xA8m theo Key h\xE1\xBB\xA3p l\xE1\xBB\x87 trong session\n        isValidHandoff = true\n    end\n\n    -- X\xC3\xB3a to\xC3\xA0n b\xE1\xBB\x99 c\xE1\xBB\x9D runtime \xC4\x91\xE1\xBB\x83 kh\xC3\xB4ng b\xE1\xBB\x8B t\xC3\xA1i s\xE1\xBB\xAD d\xE1\xBB\xA5ng\n    _rt.NexusPremiumVerified = nil\n    _rt.NexusFreemiumVerified = nil\n    _rt.NexusMainLoaded = nil\n    _rt.NexusVerifiedTier = nil\n\n    if not isValidHandoff then\n        -- Execute source tr\xE1\xBB\xB1c ti\xE1\xBA\xBFp ho\xE1\xBA\xB7c c\xE1\xBB\x91 t\xC3\xACnh set c\xE1\xBB\x9D gi\xE1\xBA\xA3 m\xE1\xBA\xA1o -> KICK ngay\n        local reason = "Bao mat: Khong the thuc thi source truc tiep. Phai qua loader chinh thuc!"\n        notify(reason)\n        pcall(function()\n            if _rt.NexusReport then\n                _rt.NexusReport("Nexus Security", reason)\n            end\n        end)\n        LP:Kick("Nexus: " .. reason)\n        while true do task.wait(9999) end\n        return\n    end\n\n    _rt.NexusFreemiumVerified = true\nend\n-- ===== END ANTI-BYPASS GUARD =====\n\nlocal runtimeEnv = (getgenv and getgenv()) or _G\n\n-- ===== NEXUSLIB LOADER =====\npcall(function() runtimeEnv.NexusStage("tai NexusLib") end)\nlocal NexusLib = runtimeEnv.NexusLib\nif not NexusLib then\n    local LIB_URL = "https://raw.githubusercontent.com/Ngmankhoi/my-hub/main/NexusLib.lua?v=20261011"\n    local source = nil\n    pcall(function()\n        if isfile and readfile and isfile("NexusLib.lua") then\n            local s = readfile("NexusLib.lua")\n            if type(s) == "string" and #s > 5000 and s:find("CreateWindow", 1, true) then source = s end\n        end\n    end)\n    if not source then\n        local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)\n        if type(reqFn) == "function" then\n            pcall(function()\n                local r = reqFn({ Url = LIB_URL, Method = "GET" })\n                local body = r and (r.Body or r.body)\n                if type(body) == "string" and #body > 5000 then source = body end\n            end)\n        end\n    end\n    if not source then\n        pcall(function() local s = game:HttpGet(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        pcall(function() local s = game:GetService("HttpService"):GetAsync(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        local msg = "[Nexus] Could not download NexusLib. This executor lacks HTTP support."\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    if type(loadstring) ~= "function" then\n        pcall(function() runtimeEnv.NexusReport("Nexus: executor not supported", "This executor has no loadstring -> the hub cannot run.\\nUse a different executor.") end)\n        return\n    end\n    local chunk, compileErr = loadstring(source, "@NexusLib.lua")\n    if not chunk then\n        local msg = "[Nexus] NexusLib compile error: " .. tostring(compileErr)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    local ok, lib = pcall(chunk)\n    if not ok or type(lib) ~= "table" then\n        local msg = "[Nexus] NexusLib runtime error: " .. tostring(lib)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    NexusLib = lib\n    runtimeEnv.NexusLib = lib\nend\n\nif runtimeEnv.MinigameAnchorLock then pcall(function() runtimeEnv.MinigameAnchorLock:Disconnect() end) end\nif runtimeEnv.NexusFrameConnection then runtimeEnv.NexusFrameConnection:Disconnect() runtimeEnv.NexusFrameConnection = nil end\nif runtimeEnv.NexusBossFightThread then task.cancel(runtimeEnv.NexusBossFightThread) runtimeEnv.NexusBossFightThread = nil end\nif runtimeEnv.NexusFightEnzoThread then task.cancel(runtimeEnv.NexusFightEnzoThread) runtimeEnv.NexusFightEnzoThread = nil end\nif runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) runtimeEnv.NexusRhyLoop = nil end\nif runtimeEnv.AntiAFKConnection then pcall(function() runtimeEnv.AntiAFKConnection:Disconnect() end) runtimeEnv.AntiAFKConnection = nil end\nif runtimeEnv.NexusSpaceGuardConnection then pcall(function() runtimeEnv.NexusSpaceGuardConnection:Disconnect() end) runtimeEnv.NexusSpaceGuardConnection = nil end\nif runtimeEnv.NexusSelectableGuardConnection then pcall(function() runtimeEnv.NexusSelectableGuardConnection:Disconnect() end) runtimeEnv.NexusSelectableGuardConnection = nil end\nif runtimeEnv.NexusNoclipConn then pcall(function() runtimeEnv.NexusNoclipConn:Disconnect() end) runtimeEnv.NexusNoclipConn = nil end\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) runtimeEnv.NexusMinigameConn = nil end\nif runtimeEnv.NexusSlamConn then pcall(function() runtimeEnv.NexusSlamConn:Disconnect() end) runtimeEnv.NexusSlamConn = nil end\n\n-- ===== SESSION EPOCH =====\nruntimeEnv.NexusEpoch = (runtimeEnv.NexusEpoch or 0) + 1\nlocal MY_EPOCH = runtimeEnv.NexusEpoch\nlocal function alive() return runtimeEnv.NexusEpoch == MY_EPOCH end\n\n-- ===== SERVICES =====\nlocal Services = {\n    Players = game:GetService("Players"),\n    ReplicatedStorage = game:GetService("ReplicatedStorage"),\n    RunService = game:GetService("RunService"),\n    VirtualUser = game:GetService("VirtualUser"),\n    UserInputService = game:GetService("UserInputService"),\n    Lighting = game:GetService("Lighting"),\n    TweenService = game:GetService("TweenService"),\n    Workspace = game:GetService("Workspace"),\n    Camera = game:GetService("Workspace").CurrentCamera,\n    HttpService = game:GetService("HttpService"),\n    GuiService = game:GetService("GuiService"),\n    TeleportService = game:GetService("TeleportService"),\n    RbxAnalyticsService = game:GetService("RbxAnalyticsService"),\n}\nlocal Players = Services.Players\nlocal ReplicatedStorage = Services.ReplicatedStorage\nlocal RunService = Services.RunService\nlocal VirtualUser = Services.VirtualUser\nlocal UserInputService = Services.UserInputService\nlocal Lighting = Services.Lighting\nlocal TweenService = Services.TweenService\nlocal Workspace = Services.Workspace\nlocal Camera = Services.Camera\n\nlocal LocalPlayer = Players.LocalPlayer\n\n-- ===== GAME DATA =====\nruntimeEnv.NexusStage("waiting for game data (Events/MainGui/Info/Data)")\nlocal Events = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Events", 30)\nif not Events then return end\nlocal StartBossFight = Events:FindFirstChild("StartBossFight")\nlocal BossPhase2Action = Events:FindFirstChild("BossPhase2Action")\nlocal MainGui = runtimeEnv.NexusNeedChild(LocalPlayer:WaitForChild("PlayerGui", 30), "MainGui", 30)\nif not MainGui then return end\nlocal Info = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Info", 30)\nif not Info then return end\nlocal Data = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Data", 30)\nif not Data then return end\n\nfor _, v in pairs(LocalPlayer:WaitForChild("PlayerGui"):GetChildren()) do\n    if v.Name:find("MobileToggle") then v:Destroy() end\nend\npcall(function()\n    for _, v in pairs(game:GetService("CoreGui"):GetChildren()) do\n        if v.Name:find("MobileToggle") then v:Destroy() end\n    end\nend)\n\nlocal CODES = {\n    "BigUPD", "23MVisits", "24MVisits", "25MVisits", "26MVisits",\n    "42KLikes", "43KLikes", "44KLikes", "45KLikes", "UIBUG"\n}\n\n-- ============================================================\n-- ===== STATE TABLE =====\n-- ============================================================\nlocal NexusState = {\n    Fishing = {\n        Flags = {\n            MainFarm = true,\n            AutoCast = false,\n            AutoSkill = false,\n            SelectedSkills = { "Z", "X", "C", "V" },\n            SkillMode = "Spam",\n            SkillSequence = "Z,X,C,V",\n            SkillDelay = 0.3,\n            AutoFarmBoss = false,\n            AutoFarmSecretBoss = false,\n            AnchorLock = false,\n            AntiAFK = false,\n            AutoSkillCheck = false,\n            BossFightMode = "Normal",\n            BossFightThread = nil,\n            AutoFightEnzo = false,\n            AutoFightLongDiaohai = false,\n            AutoLongDiaohai = false,\n            LongDiaohaiFightMode = "Normal",\n            LastCancel = 0,\n            LastFastCancel = 0,\n            LastProgress = 0,\n            LastNotify = ""\n        },\n        BossFarm = {\n            CurrentTarget = nil,\n            CurrentType = nil,\n            CurrentToken = nil,\n            CurrentRunId = 0,\n            HasHooked = false,\n            PendingCancel = false,\n            LastCast = 0,\n            LastCancel = 0,\n            LastFastCancel = 0,\n            LastProgress = 0,\n            LastNotify = ""\n        }\n    },\n    MiscFlags = {\n        FlyMode = false,\n        Noclip = false,\n        InfiniteJump = false,\n        WalkOnWater = false,\n        FullBright = false,\n        AutoSell = false,\n        AutoBuy = false,\n        AutoEquipBait = false,\n        AutoEquipRod = false,\n    },\n    islands = {\n        {name = "Island 1"\n            end\n            \n            local function clearAllBoatEsp()\n                for model, data in pairs(boatEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                boatEspHighlights = {}\n            end\n            \n            local function scanAllBoats()\n                if not boatFolder then return end\n                for _, child in ipairs(boatFolder:GetDescendants()) do\n                    if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                        if not boatEspHighlights[child] then\n                            pcall(function() createBoatEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startBoatEsp()\n                if boatEspEnabled then return end\n                boatEspEnabled = true\n                scanAllBoats()\n                \n                if boatFolder then\n                    local boatAddedConn = boatFolder.DescendantAdded:Connect(function(desc)\n                        if boatEspEnabled and typeof(desc) == "Instance" and desc:IsA("Model") and desc.Parent and typeof(desc.Parent) == "Instance" and desc.Parent:IsA("Folder") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not boatEspHighlights[desc] then\n                                    createBoatEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = boatAddedConn })\n                end\n                \n                boatEspThread = task.spawn(function()\n                    while boatEspEnabled do\n                        task.wait(10)\n                        if boatEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(boatEspHighlights) do\n                                    if not model.Parent then\n                                        removeBoatEsp(model)\n                                    end\n                                end\n                                scanAllBoats()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = "Boat ESP", Message = "Boat ESP enabled!", Duration = 2 })\n            end\n            \n            local function stopBoatEsp()\n                boatEspEnabled = false\n                if boatEspThread then\n                    task.cancel(boatEspThread)\n                    boatEspThread = nil\n                end\n                clearAllBoatEsp()\n                NexusLib:Notify({ Title = "Boat ESP", Message = "Boat ESP disabled!", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap("Toggle", "Boat ESP", {\n                Name = "Boat ESP",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startBoatEsp()\n                    else\n                        stopBoatEsp()\n                    end\n                end\n            })), "Toggle", "Boat ESP", {\n                Name = "Boat ESP",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startBoatEsp()\n                    else\n                        stopBoatEsp()\n                    end\n                end\n            })\n        end\n        \n        -- ===== SECRET ROD ESP =====\n        do\n            local secretRodEspEnabled = false\n            local secretRodEspThread = nil\n            local secretRodEspHighlights = {}\n            local secretRodFolder = workspace:FindFirstChild("SecretRod")\n            \n            local function createSecretRodEsp(rodModel)\n                if not rodModel or typeof(rodModel) ~= "Instance" or not rodModel:IsA("Model") then return end\n                if secretRodEspHighlights[rodModel] then return end\n                \n                if not rodModel.Parent or typeof(rodModel.Parent) ~= "Instance" or not rodModel.Parent:IsA("Folder") then return end\n                \n                local attachPart = rodModel:FindFirstChildWhichIsA("BasePart")\n                if not attachPart then\n                    attachPart = rodModel:FindFirstChildWhichIsA("BasePart", true)\n                end\n                if not attachPart then return end\n                \n                local highlight = Instance.new("Highlight")\n                highlight.FillColor = Color3.fromRGB(255, 215, 0)\n                highlight.FillTransparency = 0.5\n                highlight.OutlineColor = Color3.fromRGB(255, 255, 0)\n                highlight.OutlineTransparency = 0.3\n                highlight.Adornee = rodModel\n                highlight.Parent = rodModel\n                \n                local billboard = Instance.new("BillboardGui")\n                billboard.Name = "SecretRodEspBillboard"\n                billboard.Size = UDim2.new(0, 150, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new("Frame")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new("UICorner")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new("TextLabel")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(255, 215, 0)\n                label.Text = rodModel.Name\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                secretRodEspHighlights[rodModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeSecretRodEsp(rodModel)\n                local data = secretRodEspHighlights[rodModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    secretRodEspHighlights[rodModel] = nil\n                end\n            end\n            \n            local function clearAllSecretRodEsp()\n                for model, data in pairs(secretRodEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                secretRodEspHighlights = {}\n            end\n            \n            local function scanAllSecretRods()\n                if not secretRodFolder then return end\n                for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                    if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                        if not secretRodEspHighlights[child] then\n                            pcall(function() createSecretRodEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startSecretRodEsp()\n                if secretRodEspEnabled then return end\n                secretRodEspEnabled = true\n                scanAllSecretRods()\n                \n                if secretRodFolder then\n                    local rodAddedConn = secretRodFolder.DescendantAdded:Connect(function(desc)\n                        if secretRodEspEnabled and typeof(desc) == "Instance" and desc:IsA("Model") and desc.Parent and typeof(desc.Parent) == "Instance" and desc.Parent:IsA("Folder") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not secretRodEspHighlights[desc] then\n                                    createSecretRodEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = rodAddedConn })\n                end\n                \n                secretRodEspThread = task.spawn(function()\n                    while secretRodEspEnabled do\n                        task.wait(10)\n                        if secretRodEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(secretRodEspHighlights) do\n                                    if not model.Parent then\n                                        removeSecretRodEsp(model)\n                                    end\n                                end\n                                scanAllSecretRods()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = "Secret Rod ESP", Message = "Secret Rod ESP enabled!", Duration = 2 })\n            end\n            \n            local function stopSecretRodEsp()\n                secretRodEspEnabled = false\n                if secretRodEspThread then\n                    task.cancel(secretRodEspThread)\n                    secretRodEspThread = nil\n                end\n                clearAllSecretRodEsp()\n                NexusLib:Notify({ Title = "Secret Rod ESP", Message = "Secret Rod ESP disabled!", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap("Toggle", "Secret Rod ESP", {\n                Name = "Secret Rod ESP",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startSecretRodEsp()\n                    else\n                        stopSecretRodEsp()\n                    end\n                end\n            })), "Toggle", "Secret Rod ESP", {\n                Name = "Secret Rod ESP",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startSecretRodEsp()\n                    else\n                        stopSecretRodEsp()\n                    end\n                end\n            })\n        end\n        \n        -- ===== GOD ESP =====\n        do\n            local godEspEnabled = false\n            local godEspThread = nil\n            local godEspHighlights = {}\n            local godFolder = workspace:FindFirstChild("NPC") and workspace.NPC:FindFirstChild("God")\n            \n            local function createGodEsp(godModel)\n                if not godModel or typeof(godModel) ~= "Instance" or not godModel:Is       local cashVal = playerData:FindFirstChild("Cash")\n            if cashVal then stats.Cash = tostring(cashVal.Value) end\n            local rodVal = playerData:FindFirstChild("FishingRod")\n            if rodVal then stats.Rod = tostring(rodVal.Value) end\n            local crystalVal = playerData:FindFirstChild("Crystal")\n            if crystalVal then stats.Crystal = tostring(crystalVal.Value) end\n            local essenceVal = playerData:FindFirstChild("EssenceOrb")\n            if essenceVal then stats.EssenceOrb = tostring(essenceVal.Value) end\n            local baitVal = playerData:FindFirstChild("EquippedBait")\n            if baitVal then stats.Bait = tostring(baitVal.Value) end\n            local fishCaughtVal = playerData:FindFirstChild("FishCaught")\n            if fishCaughtVal then stats.FishCaught = tostring(fishCaughtVal.Value) end\n            local ticketVal = playerData:FindFirstChild("Ticket")\n            if ticketVal then stats.Ticket = tostring(ticketVal.Value) end\n            local traitRerollVal = playerData:FindFirstChild("Trait Reroll")\n            if traitRerollVal then stats.TraitReroll = tostring(traitRerollVal.Value) end\n            return stats\n        end\n        \n        local function createEspForPlayer(player)\n            if player == LocalPlayer then return end\n            local character = player.Character\n            if not character then return end\n            local head = character:FindFirstChild("Head")\n            if not head then return end\n            if head:FindFirstChild("EspBillboard") then return end\n            \n            local stats = getPlayerStats(player)\n            local billboard = Instance.new("BillboardGui")\n            billboard.Name = "EspBillboard"\n            billboard.Size = UDim2.new(0, 300, 0, 110)\n            billboard.StudsOffset = Vector3.new(0, 3, 0)\n            billboard.AlwaysOnTop = true\n            billboard.Parent = head\n            \n            local frame = Instance.new("Frame")\n            frame.Size = UDim2.new(1, 0, 1, 0)\n            frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n            frame.BackgroundTransparency = 0.6\n            frame.BorderSizePixel = 0\n            frame.Parent = billboard\n            \n            local corner = Instance.new("UICorner")\n            corner.CornerRadius = UDim.new(0, 4)\n            corner.Parent = frame\n            \n            local nameLabel = Instance.new("TextLabel")\n            nameLabel.Size = UDim2.new(1, 0, 0, 18)\n            nameLabel.Position = UDim2.new(0, 0, 0, 0)\n            nameLabel.BackgroundTransparency = 1\n            nameLabel.Font = Enum.Font.GothamBold\n            nameLabel.TextSize = 16\n            nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)\n            nameLabel.Text = player.Name\n            nameLabel.TextXAlignment = Enum.TextXAlignment.Center\n            nameLabel.Parent = frame\n            \n            local lines = {\n                string.format("Lv:%s | Cash:%s", stats.Level, stats.Cash),\n                string.format("Rod:%s", stats.Rod),\n                string.format("Bait:%s", stats.Bait),\n                string.format("Cry:%s | Ess:%s | Tick:%s | Reroll:%s", stats.Crystal, stats.EssenceOrb, stats.Ticket, stats.TraitReroll),\n                string.format("Fish:%s", stats.FishCaught)\n            }\n            \n            local yOffset = 18\n            for _, line in ipairs(lines) do\n                local label = Instance.new("TextLabel")\n                label.Size = UDim2.new(1, 0, 0, 16)\n                label.Position = UDim2.new(0, 0, 0, yOffset)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.Gotham\n                label.TextSize = 12\n                label.TextColor3 = Color3.fromRGB(200, 200, 200)\n                label.Text = line\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.Parent = frame\n                yOffset = yOffset + 16\n            end\n            \n            table.insert(espConnections, { player = player, billboard = billboard })\n        end\n        \n        local function removeEspForPlayer(player)\n            local character = player.Character\n            if not character then return end\n            local head = character:FindFirstChild("Head")\n            if not head then return end\n            local billboard = head:FindFirstChild("EspBillboard")\n            if billboard then billboard:Destroy() end\n            for i, conn in ipairs(espConnections) do\n                if conn.player == player then\n                    table.remove(espConnections, i)\n                    break\n                end\n            end\n        end\n        \n        local function clearAllEsp()\n            for _, conn in ipairs(espConnections) do\n                pcall(function()\n                    if conn.billboard and conn.billboard.Parent then\n                        conn.billboard:Destroy()\n                    end\n                end)\n            end\n            espConnections = {}\n        end\n        \n        local function updateAllEsp()\n            if not espEnabled then return end\n            clearAllEsp()\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end\n        end\n        \n        local function startEsp()\n            if espEnabled then return end\n            espEnabled = true\n            updateAllEsp()\n            \n            local playerAddedConn = Players.PlayerAdded:Connect(function(player)\n                if espEnabled then\n                    task.wait(0.5)\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end)\n            table.insert(espConnections, { conn = playerAddedConn })\n            \n            local playerRemovingConn = Players.PlayerRemoving:Connect(function(player)\n                pcall(function() removeEspForPlayer(player) end)\n            end)\n            table.insert(espConnections, { conn = playerRemovingConn })\n            \n            local characterAddedConn = Players.PlayerAdded:Connect(function(player)\n                if espEnabled then\n                    player.CharacterAdded:Connect(function()\n                        task.wait(0.5)\n                        pcall(function() createEspForPlayer(player) end)\n                    end)\n                end\n            end)\n            table.insert(espConnections, { conn = characterAddedConn })\n            \n            espThread = task.spawn(function()\n                while espEnabled do\n                    task.wait(10)\n                    if espEnabled then\n                        pcall(updateAllEsp)\n                    end\n                end\n            end)\n            \n            NexusLib:Notify({ Title = "ESP", Message = "Players ESP enabled!", Duration = 2 })\n        end\n        \n        local function stopEsp()\n            espEnabled = false\n            if espThread then\n                task.cancel(espThread)\n                espThread = nil\n            end\n            clearAllEsp()\n            for _, conn in ipairs(espConnections) do\n                if conn.conn then\n                    pcall(function() conn.conn:Disconnect() end)\n                end\n            end\n            espConnections = {}\n            NexusLib:Notify({ Title = "ESP", Message = "Players ESP disabled!", Duration = 2 })\n        end\n        \n        Cfg.register(EspSection:CreateToggle(Cfg.wrap("Toggle", "Players", {\n            Name = "Players",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startEsp()\n                else\n                    stopEsp()\n                end\n            end\n        })), "Toggle", "Players", {\n            Name = "Players",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startEsp()\n                else\n                    stopEsp()\n                end\n            end\n        })\n        \n        -- ===== BOAT ESP =====\n        do\n            local boatEspEnabled = false\n            local boatEspThread = nil\n            local boatEspHighlights = {}\n            local boatFolder = workspace:FindFirstChild("Boat")\n            \n            local function createBoatEsp(boatModel)\n                if not boatModel or typeof(boatModel) ~= "Instance" or not boatModel:IsA("Model") then return end\n                if boatEspHighlights[boatModel] then return end\n                \n                -- Only handle it when the parent is a Folder\n                if not boatModel.Parent or typeof(boatModel.Parent) ~= "Instance" or not boatModel.Parent:IsA("Folder") then return end\n                \n                local attachPart = boatModel:FindFirstChildWhichIsA("BasePart")\n                if not attachPart then\n                    attachPart = boatModel:FindFirstChildWhichIsA("BasePart", true)\n                end\n                if not attachPart then return end\n                \n                local parentName = "Boat"\n                local parent = boatModel.Parent\n                if parent and parent ~= boatFolder then\n                    parentName = parent.Name\n                end\n                \n                local highlight = Instance.new("Highlight")\n                highlight.FillColor = Color3.fromRGB(0, 150, 255)\n                highlight.FillTransparency = 0.5\n                highlight.OutlineColor = Color3.fromRGB(0, 255, 255)\n                highlight.OutlineTransparency = 0.3\n                highlight.Adornee = boatModel\n                highlight.Parent = boatModel\n                \n                local billboard = Instance.new("BillboardGui")\n                billboard.Name = "BoatEspBillboard"\n                billboard.Size = UDim2.new(0, 150, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new("Frame")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new("UICorner")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new("TextLabel")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(0, 0, 255)\n                label.Text = "Boat | " .. parentName\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                boatEspHighlights[boatModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeBoatEsp(boatModel)\n                local data = boatEspHighlights[boatModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    boatEspHighlights[boatModel] = nil\n                end\nestRod()\n    local rods = GetOwnedRods()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(rods) do\n        local s = GetRodStats(name)\n        local score = s.Power + s.Luck\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipRod(rodName)\n    if not rodName then return false end\n    return pcall(function() Events.EquipFishingRod:InvokeServer(rodName) end)\nend\n\nlocal function GetAvailableOrbs()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local orbs = {}\n    local orbFolder = p:FindFirstChild("Orb")\n    if not orbFolder then return {} end\n    for _, f in pairs(orbFolder:GetChildren()) do\n        if typeof(f) == "Instance" and typeof(f) == "Instance" and f:IsA("Folder") then\n            local eq = f:FindFirstChild("Equipping")\n            if eq and eq.Value == false then\n                table.insert(orbs, f.Name)\n            end\n        end\n    end\n    return orbs\nend\n\nlocal function GetOrbStats(orbName)\n    local p = GetPlayerData()\n    if not p then return {} end\n    local f = p.Orb:FindFirstChild(orbName)\n    if not f then return {} end\n    local stats = {}\n    for _, child in pairs(f:GetChildren()) do\n        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("NumberValue") and child.Name ~= "Equipping" and child.Name ~= "Favorite" then\n            stats[child.Name] = child.Value\n        end\n    end\n    return stats\nend\n\nlocal function GetBestOrb()\n    local orbs = GetAvailableOrbs()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(orbs) do\n        local s = GetOrbStats(name)\n        local score = (s.Damage or 0) * 2 + (s.Luck or 0) * 1.5 + (s.Cash or 0) * 0.5\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipOrb(orbName)\n    if not orbName then return false end\n    return pcall(function() Events.EquipOrb:InvokeServer(orbName) end)\nend\n\n-- Parse one Data inventory child into (fishName, weightKg, count).\n-- Real server format: Name = "FishName | 3500000 KG" (may add " | Favorite"),\n-- Value = stack count (IntValue). Older format kept as fallback.\nlocal function parseCraftWeight(str)\n    if not str or str == "" then return nil end\n    local s = tostring(str):gsub("^%s+", ""):gsub("%s+$", "")\n    s = s:gsub("%s*[Kk][Gg]%s*$", "")\n    s = s:gsub("^%s+", ""):gsub("%s+$", "")\n    local direct = tonumber(s)\n    if direct then return direct end\n    local num, suffix = s:match("^([%d%.]+)%s*([KkMmBbTt])%+?$")\n    num = tonumber(num)\n    if not num then return nil end\n    local mult = { K = 1000, M = 1000000, B = 1000000000, T = 1000000000000 }\n    local m = mult[string.upper(suffix or "")]\n    if not m then return nil end\n    return num * m\nend\n\nlocal function parseCraftFishEntry(item)\n    if not item then return nil, nil, 0 end\n    local rawName = tostring(item.Name or "")\n    rawName = string.split(rawName, "| Favorite")[1]\n    local count = 1\n    pcall(function()\n        if type(item.Value) == "number" then count = item.Value end\n    end)\n    local parts = {}\n    for part in string.gmatch(rawName, "[^|]+") do table.insert(parts, part) end\n    local function trim(s) return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "") end\n    local fishName = trim(parts[1])\n    local weight = nil\n    if #parts >= 2 then\n        weight = parseCraftWeight(string.split(trim(parts[2]), " ")[1])\n    end\n    if not weight then\n        pcall(function()\n            local w = item:GetAttribute("Weight")\n            if type(w) == "number" and w > 0 then weight = w end\n        end)\n    end\n    if (not weight) and type(item.Value) == "string" and string.find(item.Value, "|", 1, true) then\n        local vparts = {}\n        for part in string.gmatch(item.Value, "[^|]+") do table.insert(vparts, part) end\n        if #vparts >= 2 then\n            weight = parseCraftWeight(string.split(trim(vparts[2]), " ")[1])\n        end\n        if fishName == "" and #vparts >= 1 then fishName = trim(vparts[1]) end\n    end\n    if fishName == "" then return nil, nil, 0 end\n    if type(count) ~= "number" or count < 1 then count = 1 end\n    return fishName, weight, math.floor(count)\nend\n\nlocal function GetBuyableBaits()\n    local _bbNow = tick()\n    if NexusState.cachedBuyableBaits and NexusState.cachedBuyableBaitsAt and (_bbNow - NexusState.cachedBuyableBaitsAt < 30) then\n        return NexusState.cachedBuyableBaits\n    end\n    local baits = {}\n    if not Info or not Info:FindFirstChild("Bait") then return {"No bait available"} end\n    for _, child in pairs(Info.Bait:GetChildren()) do\n        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("ModuleScript") then\n            local success, mod = pcall(require, child)\n            if success and type(mod) == "table" and mod.Price and mod.Price > 0 then\n                table.insert(baits, child.Name)\n            end\n        end\n    end\n    if #baits == 0 then return {"No bait available"} end\n    NexusState.cachedBuyableBaits = baits\n    NexusState.cachedBuyableBaitsAt = _bbNow\n    return baits\nend\n\nlocal function saveRoutineFlags()\n    NexusState.savedRoutineFlags = {\n        AutoCast = Fishing.Flags.AutoCast,\n        AnchorLock = Fishing.Flags.AnchorLock,\n        AutoSkill = Fishing.Flags.AutoSkill,\n        AutoSell = MiscFlags.AutoSell,\n        AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n        AntiAFK = Fishing.Flags.AntiAFK,\n        AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n        AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n        AutoBuy = MiscFlags.AutoBuy,\n        AutoEquipBait = MiscFlags.AutoEquipBait,\n        AutoEquipRod = MiscFlags.AutoEquipRod,\n    }\nend\n\nlocal function restoreRoutineFlags()\n    if NexusState.savedRoutineFlags then\n        Fishing.Flags.AutoCast = NexusState.savedRoutineFlags.AutoCast\n        Fishing.Flags.AnchorLock = NexusState.savedRoutineFlags.AnchorLock\n        Fishing.Flags.AutoSkill = NexusState.savedRoutineFlags.AutoSkill\n        MiscFlags.AutoSell = NexusState.savedRoutineFlags.AutoSell\n        Fishing.Flags.AutoSkillCheck = NexusState.savedRoutineFlags.AutoSkillCheck\n        Fishing.Flags.AntiAFK = NexusState.savedRoutineFlags.AntiAFK\n        Fishing.Flags.AutoFarmBoss = NexusState.savedRoutineFlags.AutoFarmBoss\n        Fishing.Flags.AutoFarmSecretBoss = NexusState.savedRoutineFlags.AutoFarmSecretBoss\n        MiscFlags.AutoBuy = NexusState.savedRoutineFlags.AutoBuy\n        MiscFlags.AutoEquipBait = NexusState.savedRoutineFlags.AutoEquipBait\n        MiscFlags.AutoEquipRod = NexusState.savedRoutineFlags.AutoEquipRod\n        NexusState.savedRoutineFlags = nil\n    else\n        Fishing.Flags.AutoFarmBoss = false\n        Fishing.Flags.AutoFarmSecretBoss = false\n    end\nend\n\n-- Ticket fishing mode: auto cast + anchor lock + auto skill + rod equip,\n-- so turning on Auto Do Ticket is enough to work all 8 ticket quests.\nlocal function enableBasicFishing()\n    if not NexusState.savedRoutineFlags then saveRoutineFlags() end\n    Fishing.Flags.AutoCast = true\n    Fishing.Flags.AnchorLock = true\n    Fishing.Flags.AutoSkill = true\n    Fishing.Flags.AutoSkillCheck = true\n    MiscFlags.AutoEquipRod = true\nend\n\nlocal function disableAllFishing()\n    restoreRoutineFlags()\nend\n\n-- Teleport without the sky-drop freeze: a character held at +1000 sky sits in\n-- freefall, so AssemblyLinearVelocity grows huge. Carrying that velocity into a\n-- ground teleport slams the Humanoid into the floor and sticks it (frozen).\n-- Zero it on both ends and wake the Humanoid so movement resumes instantly.\nlocal function safeTeleport(hrp, cf)\n    if not hrp or not cf then return end\n    local model = hrp.Parent\n    local humanoid = model and model:FindFirstChildOfClass("Humanoid")\n    -- Never freeze the live character: Anchored + task.wait() inside a\n    -- RenderStepped/Heartbeat-adjacent call stalls physics for a frame and\n    -- leaves the Humanoid seated/stuck, so walking looks frozen afterwards.\n    -- PivotTo moves the whole model atomically with no Anchored pin.\n    local ok = false\n    if model then\n        pcall(function()\n            model:PivotTo(cf)\n            ok = true\n        end)\n    end\n    if not ok then\n        pcall(function()\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = cf\n        end)\n    end\n    pcall(function()\n        hrp.Anchored = false\n        hrp.AssemblyLinearVelocity = Vector3.zero\n        hrp.AssemblyAngularVelocity = Vector3.zero\n    end)\n    if humanoid then\n        pcall(function()\n            if humanoid.Seated then humanoid.Seated = false end\n            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)\n        end)\n    end\nend\n\n-- ===== EGO + TIGER CHECK (dieu kien cho Island 11) =====\n-- Island 11 chi duoc recommend khi user co ca rod Ego va Tiger trong kho.\nlocal function hasEgoAndTiger()\n    local p = GetPlayerData()\n    if not p then return false end\n    local rodFolder = p:FindFirstChild("FishingRodInventory") or p:FindFirstChild("Rod")\n    if not rodFolder then return false end\n    local hasEgo, hasTiger = false, false\n    for _, f in pairs(rodFolder:GetChildren()) do\n        local n = string.lower(tostring(f.Name))\n        if string.find(n, "ego") then hasEgo = true end\n        if string.find(n, "tiger") then hasTiger = true end\n    end\n    return hasEgo and hasTiger\nend\n\nlocal function getTotalPower()\n    local _pwNow = tick()\n    if NexusState.cachedPower and NexusState.cachedPowerAt and (_pwNow - NexusState.cachedPowerAt < 5) then\n        return NexusState.cachedPower\n    end\n    local total = 0\n    local char = LocalPlayer.Character\n    if char then\n        local stats = char:FindFirstChild("Stats")\n        if stats then\n            local rp = stats:FindFirstChild("RodPower")\n            if typeof(rp) == "Instance" and rp:IsA("NumberValue") then total = total + rp.Value end\n            local fp = stats:FindFirstChild("FishPower")\n            if typeof(fp) == "Instance" and fp:IsA("NumberValue") then total = total + fp.Value end\n        end\n        local attr = char:GetAttribute("RodPower")\n        if attr and type(attr) == "number" and attr > 0 and total == 0 then total = attr end\n    end\n    if total == 0 then\n        local userId = LocalPlayer.UserId\n        local userData = Data:FindFirstChild(tostring(userId))\n        if userData then\n            local rodNameValue = userData:FindFirstChild("FishingRod")\n            if rodNameValue then\n                local rodName = rodNameValue.Value\n                if rodName and rodName ~= "" then\n                    local rodModule = Info:FindFirstChild("Inventory") and Info.Inventory:FindFirstChild(rodName)\n                    if rodModule then\n                        local success, rodData = pcall(require, rodModule)\n                        if success and type(rodData) == "table" then\n                            total = rodData.Power or 0\n                        end\n                    end\n                end\n            end\n        end\n    end\n  